INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('3da7ca0b-3d8c-5cbf-8ed7-761fa7dd4999', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 7, 7, 'Polonium-210 (proton number 84) decays by emitting an α-particle. What is the proton number of the daughter nucleus?', NULL, 1, 'numeric'::answer_type, '82', NULL, false, NULL, false, NULL, 'An α-particle carries away 2 protons: Z = 84 − 2 = 82. Mark scheme (1 mark). A1: Z = 82.', 1, NULL, NULL),
('ddc37487-f6f5-560a-a931-ed42bd479c15', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 8, 8, 'Which particles leave the nucleus in β⁻ decay?', NULL, 1, 'multiple_choice'::answer_type, 'An electron and an antineutrino', NULL, false, NULL, false, NULL, 'β⁻ decay: n → p + e⁻ + ν̄. Mark scheme (1 mark). B1: C (An electron and an antineutrino).', 1, NULL, NULL),
('3eff6ec0-f242-5502-8a48-8983157cc10b', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 9, 9, 'Carbon-14 decays by β⁻ emission. What is the nucleon number of the daughter nucleus?', NULL, 1, 'numeric'::answer_type, '14', NULL, false, NULL, false, NULL, 'An electron has nucleon number 0, so A = 14 − 0 = 14. Mark scheme (1 mark). A1: A = 14.', 1, NULL, NULL),
('b6ca4386-6df3-5438-a457-0f38c15f7e5e', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 10, 10, 'Which particle is emitted as β⁺ radiation?', NULL, 1, 'multiple_choice'::answer_type, 'A positron', NULL, false, NULL, false, NULL, 'β⁺ particles are positrons, the antiparticles of electrons. Mark scheme (1 mark). B1: A (A positron).', 1, NULL, NULL),
('a4ed095f-3dad-5662-b3cc-2f7865131b84', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 11, 11, 'Sodium-22 (proton number 11) decays by β⁺ emission. Calculate the proton number of the daughter nucleus.', NULL, 1, 'numeric'::answer_type, '10', NULL, false, NULL, false, NULL, 'A proton becomes a neutron: Z = 11 − 1 = 10. Mark scheme (2 marks). C1: β⁺ lowers Z by one. A1: Z = 10.', 2, NULL, NULL),
('9b733326-440f-5420-98bf-52327b2601a1', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 12, 12, 'A nucleus emits a γ-ray photon. What happens to its nucleon number and proton number?', NULL, 1, 'multiple_choice'::answer_type, 'Neither changes', NULL, false, NULL, false, NULL, 'A γ-photon carries energy only, with no charge or nucleons. Mark scheme (1 mark). B1: D (Neither changes).', 1, NULL, NULL),
('0d4c2f63-abe8-5c27-867f-8300c3fa8722', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 13, 13, 'Thorium-232 (proton number 90) emits an α-particle. How many neutrons are in the daughter nucleus?', NULL, 1, 'numeric'::answer_type, '140', NULL, false, NULL, false, NULL, 'Daughter: A = 232 − 4 = 228, Z = 90 − 2 = 88, so N = 228 − 88 = 140. Mark scheme (2 marks). C1: A and Z of daughter. A1: N = 140.', 2, NULL, NULL),
('9c5124d6-8b73-5427-b48d-e101ab736595', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 14, 14, 'In β⁻ decay, what change happens inside the nucleus?', NULL, 1, 'multiple_choice'::answer_type, 'A neutron changes into a proton', NULL, false, NULL, false, NULL, 'A neutron turns into a proton, emitting an electron and an antineutrino: n → p + e⁻ + ν̄. Mark scheme (1 mark). B1: B (A neutron changes into a proton).', 1, NULL, NULL),
('07673f07-e25c-5797-9a1a-d86ee0180ae5', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 15, 15, 'Uranium-238 has proton number 92. How many neutrons does its nucleus contain?', NULL, 1, 'numeric'::answer_type, '146', NULL, false, NULL, false, NULL, 'N = A − Z = 238 − 92 = 146. Mark scheme (2 marks). C1: N = A − Z. A1: N = 146.', 2, NULL, NULL),
('e000c0e6-046a-57ed-ae2b-b7540b2ef8d6', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 16, 16, 'Which particle is emitted together with the positron in β⁺ decay?', NULL, 1, 'multiple_choice'::answer_type, 'A neutrino', NULL, false, NULL, false, NULL, 'A proton becomes a neutron, a positron and a neutrino: p → n + e⁺ + ν. Mark scheme (1 mark). B1: C (A neutrino).', 1, NULL, NULL),
('6b800816-9c28-5ef5-8f62-7cd4907c74ad', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 17, 17, 'Uranium-238 eventually becomes lead-206 by a series of α and β⁻ decays. How many α-particles are emitted in the whole series?', NULL, 1, 'numeric'::answer_type, '8', NULL, false, NULL, false, NULL, 'Only α decay changes A, by 4 each time: number = (238 − 206) ÷ 4 = 8. Mark scheme (2 marks). C1: β decay leaves A unchanged. A1: α decays = 8.', 2, NULL, NULL),
('086d2573-4cce-577e-b75f-d2d5a608e873', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 18, 18, 'Which description of an α-particle is correct?', NULL, 1, 'multiple_choice'::answer_type, 'A helium-4 nucleus: two protons and two neutrons', NULL, false, NULL, false, NULL, 'Its charge is +2e and its nucleon number is 4. Mark scheme (1 mark). B1: A (A helium-4 nucleus: two protons and two neutrons).', 1, NULL, NULL),
('b4f03c01-7625-5cf9-bbd1-58545fe17ac3', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 19, 19, 'Two deuterium (hydrogen-2) nuclei fuse to form helium-3 and one other particle. What is the nucleon number of that particle?', NULL, 1, 'numeric'::answer_type, '1', NULL, false, NULL, false, NULL, 'Nucleon number is conserved, so A = 2 + 2 − 3 = 1. The particle is a neutron. Mark scheme (2 marks). C1: nucleon number conserved. A1: A = 1.', 2, NULL, NULL),
('08224e84-c051-5437-b444-0b884bbc01fa', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 20, 20, 'Which two quantities must be the same on both sides of every nuclear equation?', NULL, 1, 'multiple_choice'::answer_type, 'Total nucleon number and total charge (proton number)', NULL, false, NULL, false, NULL, 'A and Z are conserved in nuclear reactions. Mark scheme (1 mark). B1: D (Total nucleon number and total charge (proton number)).', 1, NULL, NULL),
('c72ec97a-ff7a-5aa7-b77d-b298e99254df', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 21, 21, 'Cobalt-60 (proton number 27) decays by β⁻ emission followed by γ emission. What is the proton number of the final nucleus?', NULL, 1, 'numeric'::answer_type, '28', NULL, false, NULL, false, NULL, 'β⁻ raises Z by one, γ changes nothing: Z = 27 + 1 = 28. Mark scheme (2 marks). C1: β⁻ adds one proton. A1: Z = 28.', 2, NULL, NULL),
('d260fdc1-a087-5d11-b1f3-498144bd9945', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 22, 22, 'Bismuth-212 emits an α-particle. What is the nucleon number of the daughter nucleus?', NULL, 1, 'numeric'::answer_type, '208', NULL, false, NULL, false, NULL, 'The α-particle removes 4 nucleons: A = 212 − 4 = 208. Mark scheme (1 mark). A1: A = 208.', 1, NULL, NULL),
('7b7a0bab-8711-506a-8ea5-ca6eec7f80ed', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 23, 23, 'Radon-222 (proton number 86) decays by α emission, the daughter decays by α emission, and the next two decays are β⁻. What is the proton number of the final nucleus?', NULL, 2, 'numeric'::answer_type, '84', NULL, false, NULL, false, NULL, 'Z = 86 − 2 − 2 + 1 + 1 = 84. Mark scheme (3 marks). C1: −2 for each α. C1: +1 for each β⁻. A1: Z = 84.', 3, NULL, NULL),
('f3ccfeca-bd19-574b-a3ea-20c5c476df88', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 24, 24, 'Uranium-235 absorbs a neutron and splits into xenon-140 and strontium-94, releasing some neutrons. How many neutrons are released?', NULL, 2, 'numeric'::answer_type, '2', NULL, false, NULL, false, NULL, 'Nucleon numbers: 235 + 1 = 140 + 94 + n, so n = 236 − 234 = 2. Mark scheme (3 marks). C1: nucleon number conserved. C1: include the absorbed neutron. A1: neutrons = 2.', 3, NULL, NULL),
('4f7e904c-4ac6-5dc7-aeb8-3b9c69af819c', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 25, 25, 'Which of these nuclear equations is balanced? (Each nucleus is written as element-A with proton number Z in brackets.)', NULL, 2, 'multiple_choice'::answer_type, 'radium-226 (88) → radon-222 (86) + helium-4 (2)', NULL, false, NULL, false, NULL, 'A: 226 = 222 + 4; Z: 88 = 86 + 2. Mark scheme (3 marks). C1: check A. C1: check Z. A1: B (radium-226 (88) → radon-222 (86) + helium-4 (2)).', 3, NULL, NULL),
('667ac3e3-83e2-5db3-8031-10826c25827f', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 26, 26, 'Rutherford fired α-particles at nitrogen-14 (proton number 7); a proton was emitted. What is the proton number of the nucleus formed?', NULL, 2, 'numeric'::answer_type, '8', NULL, false, NULL, false, NULL, 'Z = 7 + 2 − 1 = 8, which is oxygen. Mark scheme (3 marks). C1: add the α-particle. C1: subtract the proton. A1: Z = 8.', 3, NULL, NULL),
('959d0414-e563-5f9e-a837-b611af2b788a', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 27, 27, 'In the same reaction (nitrogen-14 + α-particle → new nucleus + proton), what is the nucleon number of the new nucleus?', NULL, 2, 'numeric'::answer_type, '17', NULL, false, NULL, false, NULL, 'A = 14 + 4 − 1 = 17, so oxygen-17 is formed. Mark scheme (3 marks). C1: nucleon numbers added. C1: proton subtracted. A1: A = 17.', 3, NULL, NULL),
('0eaa5dbd-33db-54ea-bb72-08fab7209278', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 28, 28, 'Why did Pauli propose that a neutrino is emitted in β decay?', NULL, 2, 'multiple_choice'::answer_type, 'β-particles have a continuous range of energies, so another particle must carry the missing energy', NULL, false, NULL, false, NULL, 'Without a third particle, energy and momentum would not be conserved. Mark scheme (3 marks). C1: continuous β spectrum. C1: energy conservation needs a third particle. A1: C (β-particles have a continuous range of energies, so another particle must carry the missing energy).', 3, NULL, NULL),
('0ad3ab95-f8c5-5cf4-9b7a-48bacb6bfc65', 'aae53119-5afd-4055-b81b-60e6244772d7', '20eb2251-a133-4766-96d3-065fb00dfd07', 'a-level', '29.1', '9702 coursebook 29.1 · Balanced equations', 29, 29, 'Thorium-232 (proton number 90) decays to lead-208 (proton number 82) through a series of α and β⁻ decays. Calculate the number of β⁻ decays.', NULL, 2, 'numeric'::answer_type, '4', NULL, false, NULL, false, NULL, 'α decays = (232 − 208) ÷ 4 = 6, lowering Z by 12 to 78. β⁻ decays each raise Z by 1: number = 82 − 78 = 4. Mark scheme (4 marks). C1: number of α decays. C1: effect of α on Z. C1: β⁻ count from Z. A1: β⁻ decays = 4.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 300" role="img" aria-labelledby="fg3b1a92fa-t fg3b1a92fa-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3b1a92fa-t">Thorium-232 to lead-208</title><desc id="fg3b1a92fa-d">Chart of proton number against neutron number marking thorium-232 (142 neutrons, 90 protons) and lead-208 (126 neutrons, 82 protons), the start and end of the decay series.</desc><line x1="29.4" y1="34" x2="29.4" y2="252" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="88.2" y1="34" x2="88.2" y2="252" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="147" y1="34" x2="147" y2="252" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="205.7" y1="34" x2="205.7" y2="252" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="264.5" y1="34" x2="264.5" y2="252" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="323.2" y1="34" x2="323.2" y2="252" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="252" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="252" x2="382" y2="252" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="220.9" x2="382" y2="220.9" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="189.7" x2="382" y2="189.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="158.6" x2="382" y2="158.6" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="127.4" x2="382" y2="127.4" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="96.3" x2="382" y2="96.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="65.1" x2="382" y2="65.1" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="252" x2="388" y2="252" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="252" x2="29.4" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,252 385.7,255 385.7,249" style="fill:currentColor;stroke:none"/><polygon points="29.4,24 32.4,30.3 26.5,30.3" style="fill:currentColor;stroke:none"/><line x1="29.4" y1="252" x2="29.4" y2="256" style="stroke:currentColor;stroke-width:0.9;fill: