('8a80115f-161d-5294-9794-41c997228f2c', '0eaa5dbd-33db-54ea-bb72-08fab7209278', 'The daughter nucleus was found to be charged', 'B', false, 1),
('5cda5efc-adfc-5672-a79a-d70b3495673e', '0eaa5dbd-33db-54ea-bb72-08fab7209278', 'β-particles have a continuous range of energies, so another particle must carry the missing energy', 'C', true, 2),
