('1223c4bb-39b3-51d6-a2c4-48f261b0b110', '8c944de4-2a6f-5ab9-9fd3-b2d047eacfcf', 'None of them can', 'C', false, 2),
('35e604f4-602b-566d-8d36-061965540613', '8c944de4-2a6f-5ab9-9fd3-b2d047eacfcf', 'β⁺ decay', 'D', true, 3),
('19d68f1e-6c43-5034-a971-26614ab2f5e3', 'cc709ff9-0eb2-5ee5-8097-9a377721f990', 'An up quark changes into a down quark', 'A', false, 0),
('de510510-3e80-5410-ac61-cb802a710564', 'cc709ff9-0eb2-5ee5-8097-9a377721f990', 'A down quark changes into an up quark', 'B', true, 1),
('017a673d-dc10-516c-87c7-14a337c2fe55', 'cc709ff9-0eb2-5ee5-8097-9a377721f990', 'A down quark changes into a strange quark', 'C', false, 2),
('39732511-e024-58e5-8bea-c4e7c485472c', 'cc709ff9-0eb2-5ee5-8097-9a377721f990', 'Nothing changes; only an electron is emitted', 'D', false, 3),
('d715fa1e-81f5-57c8-a52a-5ae9c354c28d', 'ef683903-6fd9-5181-a0a4-e60a8144eb94', 'Charge only', 'A', false, 0),
('85102375-5bbe-54e8-8f38-584717f41b8c', 'ef683903-6fd9-5181-a0a4-e60a8144eb94', 'Nucleon number only', 'B', false, 1),
