('6e354322-8aad-5260-ad52-964ff5e7db69', 'ef683903-6fd9-5181-a0a4-e60a8144eb94', 'Proton number and neutron number separately', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('683132c0-94c4-5ba6-b040-b90f9901e428', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 7, 7, 'Calculate the energy equivalent of 1.0 g of matter, in units of 10¹³ J. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '9', '10¹³ J', false, NULL, false, NULL, 'E = mc² = 1.0 × 10⁻³ × (3.00 × 10⁸)² = 9.0 × 10¹³ J. Mark scheme (2 marks). C1: E = mc². A1: E = 9.0 × 10¹³ J.', 2, NULL, NULL),
('bb89358f-c802-5cf3-bbd4-93ae64f94e8f', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 8, 8, 'What does E = mc² tell us?', NULL, 1, 'multiple_choice'::answer_type, 'Mass and energy are equivalent: a change in energy goes with a change in mass', NULL, false, NULL, false, NULL, 'Any energy change ΔE corresponds to a mass change ΔE/c². Mark scheme (1 mark). B1: C (Mass and energy are equivalent: a change in energy goes with a change in mass).', 1, NULL, NULL),
('a3da6f5a-636c-5675-a912-df3f61598885', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 9, 9, 'What mass is equivalent to 1.0 J of energy? Give your answer in units of 10⁻¹⁷ kg. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '1.111', '10⁻¹⁷ kg', false, NULL, false, NULL, 'm = E/c² = 1.0 ÷ (3.00 × 10⁸)² = 1.11 × 10⁻¹⁷ kg. Mark scheme (2 marks). C1: m = E/c². A1: m = 1.11 × 10⁻¹⁷ kg.', 2, NULL, NULL),
('cd533658-5865-5458-a631-0a03971dd03a', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 10, 10, 'How is the unified atomic mass unit u defined?', NULL, 1, 'multiple_choice'::answer_type, 'One twelfth of the mass of a carbon-12 atom', NULL, false, NULL, false, NULL, 'u = 1.66 × 10⁻²⁷ kg. Mark scheme (1 mark). B1: A (One twelfth of the mass of a carbon-12 atom).', 1, NULL, NULL),
('b960ec5d-bd21-573b-9698-a56bdc1607b0', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 11, 11, 'Convert a mass of 0.0050 u into kilograms, in units of 10⁻³⁰ kg. Take 1 u = 1.66 × 10⁻²⁷ kg.', NULL, 1, 'numeric'::answer_type, '8.3', '10⁻³⁰ kg', false, NULL, false, NULL, 'm = 0.0050 × 1.66 × 10⁻²⁷ = 8.30 × 10⁻³⁰ kg. Mark scheme (2 marks). C1: × 1.66 × 10⁻²⁷. A1: m = 8.30 × 10⁻³⁰ kg.', 2, NULL, NULL),
('4495fe63-85e4-5689-bc7e-b763f68d94d5', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 12, 12, 'When separate protons and neutrons join to form a nucleus, what happens to the total mass?', NULL, 1, 'multiple_choice'::answer_type, 'It decreases, because energy is released', NULL, false, NULL, false, NULL, 'The released binding energy corresponds to the mass defect. Mark scheme (1 mark). B1: D (It decreases, because energy is released).', 1, NULL, NULL),
('7b744227-016b-5ed6-b116-5d113877cbf4', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 13, 13, 'A reaction converts 2.0 × 10⁻³⁰ kg of mass into energy. Calculate the energy in MeV. Take c = 3.00 × 10⁸ m s⁻¹. Take 1 MeV = 1.60 × 10⁻¹³ J.', NULL, 1, 'numeric'::answer_type, '1.125', 'MeV', false, NULL, false, NULL, 'E = 2.0 × 10⁻³⁰ × (3.00 × 10⁸)² = 1.8 × 10⁻¹³ J. In MeV: 1.8 × 10⁻¹³ ÷ 1.60 × 10⁻¹³ = 1.12. Mark scheme (2 marks). C1: E = mc² then ÷ 1.60 × 10⁻¹³. A1: E = 1.12 MeV.', 2, NULL, NULL),
('6e531e08-225e-546c-9586-b157d83d401e', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 14, 14, 'What kind of quantity is measured in MeV?', NULL, 1, 'multiple_choice'::answer_type, 'Energy', NULL, false, NULL, false, NULL, '1 MeV = 1.60 × 10⁻¹³ J; it is also used for mass via E = mc². Mark scheme (1 mark). B1: B (Energy).', 1, NULL, NULL),
('57d32efd-306c-52b7-8714-d60d31d4d37c', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 15, 15, 'A nuclear reaction has a mass defect of 0.010 u. Taking 1 u as equivalent to 931.5 MeV, calculate the energy released in MeV.', NULL, 1, 'numeric'::answer_type, '9.315', 'MeV', false, NULL, false, NULL, 'E = 0.010 × 931.5 = 9.315 MeV. Mark scheme (2 marks). C1: × 931.5. A1: E = 9.315 MeV.', 2, NULL, NULL),
('9c3cbe61-e8f0-5fce-8130-c13cde697ca8', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 16, 16, 'Why are mass changes not noticed in chemical reactions?', NULL, 1, 'multiple_choice'::answer_type, 'The energy changes are so small that Δm = ΔE/c² is far too tiny to measure', NULL, false, NULL, false, NULL, 'A few eV per molecule gives a mass change of about 10⁻⁹ of the total. Mark scheme (1 mark). B1: C (The energy changes are so small that Δm = ΔE/c² is far too tiny to measure).', 1, NULL, NULL),
('4cc9afa2-49b4-553e-84b5-65e5303869f1', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 17, 17, 'A reaction releases 1.0 MJ. Calculate the mass lost, in units of 10⁻¹¹ kg. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '1.111', '10⁻¹¹ kg', false, NULL, false, NULL, 'Δm = E/c² = 1.0 × 10⁶ ÷ (3.00 × 10⁸)² = 1.11 × 10⁻¹¹ kg. Mark scheme (2 marks). C1: Δm = E/c². A1: Δm = 1.11 × 10⁻¹¹ kg.', 2, NULL, NULL),
('f86fa476-9485-517b-a4d7-6f85c211e757', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 18, 18, 'In a nuclear reaction, which quantity is always conserved?', NULL, 1, 'multiple_choice'::answer_type, 'Total mass–energy', NULL, false, NULL, false, NULL, 'Rest mass can change into energy and back, but mass–energy is conserved. Mark scheme (1 mark). B1: A (Total mass–energy).', 1, NULL, NULL),
('1f6d0538-1051-5975-939a-e873560bfb32', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 19, 19, 'A reaction loses 1.0 × 10⁻²⁹ kg of mass. Calculate the energy released in MeV. Take c = 3.00 × 10⁸ m s⁻¹. Take 1 MeV = 1.60 × 10⁻¹³ J.', NULL, 1, 'numeric'::answer_type, '5.625', 'MeV', false, NULL, false, NULL, 'E = 1.0 × 10⁻²⁹ × (3.00 × 10⁸)² = 9.0 × 10⁻¹³ J. In MeV: 9.0 × 10⁻¹³ ÷ 1.60 × 10⁻¹³ = 5.62. Mark scheme (2 marks). C1: E = mc² then convert. A1: E = 5.62 MeV.', 2, NULL, NULL),
('12d4d73a-8bcd-56ab-b7b3-281414c40682', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 20, 20, 'The rest energy of an electron is about', NULL, 1, 'multiple_choice'::answer_type, '0.51 MeV', NULL, false, NULL, false, NULL, 'mₑc² = 9.11 × 10⁻³¹ × (3.00 × 10⁸)² ≈ 8.2 × 10⁻¹⁴ J ≈ 0.51 MeV. Mark scheme (1 mark). B1: D (0.51 MeV).', 1, NULL, NULL),
('4349f464-38f7-5ef4-b2d8-dec59e424c7d', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 21, 21, 'The Sun loses 4.3 × 10⁹ kg of mass each second. Calculate its power output in units of 10²⁶ W. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '3.87', '10²⁶ W', false, NULL, false, NULL, 'P = (Δm/t)c² = 4.3 × 10⁹ × (3.00 × 10⁸)² = 3.87 × 10²⁶ W. Mark scheme (2 marks). C1: P = rate of mass loss × c². A1: P = 3.87 × 10²⁶ W.', 2, NULL, NULL),
('10fe9088-e11c-53b0-905b-0d12dd1117a0', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 22, 22, 'Calculate the rest energy of a proton (mass 1.67 × 10⁻²⁷ kg) in MeV. Take c = 3.00 × 10⁸ m s⁻¹. Take 1 MeV = 1.60 × 10⁻¹³ J.', NULL, 1, 'numeric'::answer_type, '939.4', 'MeV', false, NULL, false, NULL, 'E = 1.67 × 10⁻²⁷ × (3.00 × 10⁸)² = 1.503 × 10⁻¹⁰ J. In MeV: 1.503 × 10⁻¹⁰ ÷ 1.60 × 10⁻¹³ = 939. Mark scheme (2 marks). C1: E = mc² in MeV. A1: E = 939 MeV.', 2, NULL, NULL),
('62ab014e-ada9-57df-bc29-303ba666b0c6', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 23, 23, 'Express 1.0 MeV in units of 10⁻¹³ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.6', '10⁻¹³ J', false, NULL, false, NULL, 'E = 1.0 × 10⁶ × 1.60 × 10⁻¹⁹ = 1.6 × 10⁻¹³ J. Mark scheme (1 mark). A1: E = 1.6 × 10⁻¹³ J.', 1, NULL, NULL),
('143be9d2-0750-53e5-a0fc-5e9c7e005d53', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 24, 24, 'A nuclear battery loses 2.0 × 10⁻¹⁴ kg of mass as energy. Calculate the energy released, in kJ. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '1.8 kJ', 'kJ', false, NULL, false, NULL, 'E = mc² = 2.0 × 10⁻¹⁴ × (3.00 × 10⁸)² = 1800 J. In kJ: 1800 ÷ 10³ = 1.80. Mark scheme (2 marks). C1: E = mc² then convert. A1: E = 1.8 kJ.', 2, NULL, NULL),
('df21b11e-b945-5253-a3c4-7a89f5a976d5', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 25, 25, 'A nuclear power station produces 1.0 GW of thermal power for one year (3.16 × 10⁷ s). Calculate the mass converted into energy. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '0.3511', 'kg', false, NULL, false, NULL, 'E = Pt = 1.0 × 10⁹ × 3.16 × 10⁷ = 3.16 × 10¹⁶ J. Δm = 3.16 × 10¹⁶ ÷ (3.00 × 10⁸)² = 0.351 kg. Mark scheme (3 marks). C1: E = Pt. C1: Δm = E/c². A1: Δm = 0.351 kg.', 3, NULL, NULL),
('ea69192b-cf38-5601-aec0-14b035179ffb', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 26, 26, 'An electron and a positron at rest annihilate completely. Calculate the total energy released, in units of 10⁻¹³ J. Take mₑ = 9.11 × 10⁻³¹ kg and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '1.64', '10⁻¹³ J', false, NULL, false, NULL, 'E = 2mₑc² = 2 × 9.11 × 10⁻³¹ × (3.00 × 10⁸)² = 1.64 × 10⁻¹³ J. Mark scheme (3 marks). C1: two rest masses. C1: E = mc². A1: E = 1.64 × 10⁻¹³ J.', 3, NULL, NULL),
('f9272e83-8fb6-5dd3-8ad8-2fa76fa4609f', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 27, 27, 'An electron and a positron at rest annihilate, producing two identical photons. Calculate the wavelength of each photon in units of 10⁻¹² m. Take mₑ = 9.11 × 10⁻³¹ kg, c = 3.00 × 10⁸ m s⁻¹ and h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '2.426', '10⁻¹² m', false, NULL, false, NULL, 'Each photon has E = mₑc² = 9.11 × 10⁻³¹ × (3.00 × 10⁸)² = 8.199 × 10⁻¹⁴ J. λ = hc/E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 8.199 × 10⁻¹⁴ = 2.43 × 10⁻¹² m. Mark scheme (4 marks). M1: two photons share 2mₑc². C1: E per photon. C1: λ = hc/E. A1: λ = 2.43 × 10⁻¹² m.', 4, NULL, NULL),
('a0228684-9d05-5f59-a9b8-28403ff79e76', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 28, 28, 'In a nuclear reaction the total rest mass of the products is less than that of the reactants. What follows?', NULL, 2, 'multiple_choice'::answer_type, 'Energy is released, mostly as kinetic energy of the products', NULL, false, NULL, false, NULL, 'ΔE = Δm c² appears as kinetic energy and radiation. Mark scheme (3 marks). C1: Δm > 0 means energy released. C1: appears as kinetic energy. A1: B (Energy is released, mostly as kinetic energy of the products).', 3, NULL, NULL),
('f5962166-521e-59e3-98ca-1ac782033fbf', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 29, 29, 'A reaction has a mass defect of 0.0024 u. Calculate the energy released, in units of 10⁻¹³ J. Take 1 u = 1.66 × 10⁻²⁷ kg and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '3.586', '10⁻¹³ J', false, NULL, false, NULL, 'Δm = 0.0024 × 1.66 × 10⁻²⁷ = 3.984 × 10⁻³⁰ kg. E = 3.984 × 10⁻³⁰ × (3.00 × 10⁸)² = 3.59 × 10⁻¹³ J. Mark scheme (3 marks). C1: u to kg. C1: E = mc². A1: E = 3.59 × 10⁻¹³ J.', 3, NULL, NULL),
('69c7fa6b-202d-5061-bf04-643721c43ad4', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 30, 30, 'A gamma photon can create an electron–positron pair if it has at least enough energy for their rest masses. Calculate this threshold energy in MeV. Take mₑ = 9.11 × 10⁻³¹ kg and c = 3.00 × 10⁸ m s⁻¹. Take 1 MeV = 1.60 × 10⁻¹³ J.', NULL, 2, 'numeric'::answer_type, '1.025', 'MeV', false, NULL, false, NULL, 'E = 2mₑc² = 2 × 9.11 × 10⁻³¹ × (3.00 × 10⁸)² = 1.640 × 10⁻¹³ J. In MeV: 1.640 × 10⁻¹³ ÷ 1.60 × 10⁻¹³ = 1.02. Mark scheme (3 marks). C1: 2mₑc². C1: in MeV. A1: E = 1.02 MeV.', 3, NULL, NULL),
('bd979c38-abd9-568b-9a55-0c7247f12253', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 31, 31, 'After fission, why is the total mass of the fragments and neutrons less than the mass of the original nucleus and neutron?', NULL, 2, 'multiple_choice'::answer_type, 'The products are more tightly bound, and the extra binding energy is released', NULL, false, NULL, false, NULL, 'Higher binding energy per nucleon means lower mass per nucleon. Mark scheme (3 marks). C1: products more tightly bound. C1: energy released corresponds to Δm. A1: C (The products are more tightly bound, and the extra binding energy is released).', 3, NULL, NULL),
('ed38e962-97c0-5270-80a4-94b57d662a56', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 32, 32, 'The fusion of deuterium and tritium has a mass defect of 0.0189 u. Taking 1 u as equivalent to 931.5 MeV, calculate the energy released.', NULL, 2, 'numeric'::answer_type, '17.61', 'MeV', false, NULL, false, NULL, 'E = 0.0189 × 931.5 = 17.6 MeV. Mark scheme (3 marks). C1: × 931.5. C1: substitution. A1: E = 17.6 MeV.', 3, NULL, NULL),
('899fe72a-37c9-5900-be97-b594b431c18c', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 33, 33, 'Each fission of uranium-235 releases about 200 MeV. Calculate the energy released when 1.0 kg of uranium-235 (molar mass 235 g mol⁻¹) undergoes fission, in units of 10¹³ J. Take N_A = 6.02 × 10²³ mol⁻¹. Take 1 MeV = 1.60 × 10⁻¹³ J.', NULL, 2, 'numeric'::answer_type, '8.197', '10¹³ J', false, NULL, false, NULL, 'N = 1000 ÷ 235 × 6.02 × 10²³ = 2.562 × 10²⁴. E = 2.562 × 10²⁴ × 200 × 1.60 × 10⁻¹³ = 8.20 × 10¹³ J. Mark scheme (4 marks). C1: number of nuclei. C1: energy per fission in J. C1: total. A1: E = 8.20 × 10¹³ J.', 4, NULL, NULL),
('5c6a8453-9b55-59f0-b36f-645722d94c9b', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 34, 34, 'A kettle of water is heated from 20 °C to 100 °C. What happens to the mass of the water?', NULL, 2, 'multiple_choice'::answer_type, 'It increases by a tiny amount equal to the energy supplied ÷ c²', NULL, false, NULL, false, NULL, 'Internal energy has mass; ΔE/c² is around 10⁻¹² kg. Mark scheme (3 marks). C1: energy gained. C1: Δm = ΔE/c² tiny. A1: A (It increases by a tiny amount equal to the energy supplied ÷ c²).', 3, NULL, NULL),
('302c682c-e7b7-5596-bc76-6b763119a892', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 35, 35, '1.0 kg of water is heated through 80 K (specific heat capacity 4200 J kg⁻¹ K⁻¹). Calculate the increase in its mass, in units of 10⁻¹² kg. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '3.733', '10⁻¹² kg', false, NULL, false, NULL, 'ΔE = 1.0 × 4200 × 80 = 3.36 × 10⁵ J. Δm = 3.36 × 10⁵ ÷ (3.00 × 10⁸)² = 3.73 × 10⁻¹² kg. Mark scheme (3 marks). C1: ΔE = mcΔθ. C1: Δm = ΔE/c². A1: Δm = 3.73 × 10⁻¹² kg.', 3, NULL, NULL),
('eeb1f0a2-9ba3-52f6-bd96-dfa0210d4254', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 36, 36, 'In deuterium–tritium fusion, reactants of total mass 5.030 u lose 0.0189 u. What percentage of the mass is converted into energy?', NULL, 2, 'numeric'::answer_type, '0.3757', '%', false, NULL, false, NULL, 'Percentage = 0.0189 ÷ 5.030 × 100 = 0.376 %. Mark scheme (3 marks). C1: fraction. C1: × 100. A1: percentage = 0.376%.', 3, NULL, NULL),
('27fda783-d896-50bc-8582-b0fce3d70c6c', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 37, 37, 'Why does a nuclear reaction release millions of times more energy per kilogram of fuel than burning a chemical fuel?', NULL, 2, 'multiple_choice'::answer_type, 'Nuclear binding energies are millions of electronvolts per nucleon, compared with a few electronvolts per bond', NULL, false, NULL, false, NULL, 'MeV per reaction compared with eV per reaction. Mark scheme (3 marks). C1: MeV scale. C1: eV scale. A1: D (Nuclear binding energies are millions of electronvolts per nucleon, compared with a few electronvolts per bond).', 3, NULL, NULL),
('6d57bb04-c068-5c99-8022-917760e75131', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 38, 38, 'What mass is equivalent to 1.0 MeV? Give your answer in units of 10⁻³⁰ kg. Take c = 3.00 × 10⁸ m s⁻¹. Take 1 MeV = 1.60 × 10⁻¹³ J.', NULL, 2, 'numeric'::answer_type, '1.778', '10⁻³⁰ kg', false, NULL, false, NULL, 'm = E/c² = 1.60 × 10⁻¹³ ÷ (3.00 × 10⁸)² = 1.78 × 10⁻³⁰ kg. Mark scheme (3 marks). C1: MeV to J. C1: m = E/c². A1: m = 1.78 × 10⁻³⁰ kg.', 3, NULL, NULL),
('dfeef853-0d29-5d1d-994d-d625d1f737c8', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 39, 39, 'An α-particle has a kinetic energy of 5.3 MeV. Express this in units of 10⁻¹³ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '8.48', '10⁻¹³ J', false, NULL, false, NULL, 'E = 5.3 × 10⁶ × 1.60 × 10⁻¹⁹ = 8.48 × 10⁻¹³ J. Mark scheme (3 marks). C1: MeV to eV. C1: eV to J. A1: E = 8.48 × 10⁻¹³ J.', 3, NULL, NULL),
('5cd6c069-1c6c-50d7-9d35-77059d13c7c2', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 40, 40, 'Which process shows energy turning into mass?', NULL, 2, 'multiple_choice'::answer_type, 'A γ-ray photon producing an electron–positron pair', NULL, false, NULL, false, NULL, 'Pair production creates rest mass from photon energy; annihilation is the reverse. Mark scheme (4 marks). C1: pair production. C1: photon energy ≥ 2mₑc². C1: annihilation is the reverse. A1: B (A γ-ray photon producing an electron–positron pair).', 4, NULL, NULL),
('b2e253b5-57b3-57d4-9169-7217e1b113a5', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 41, 41, 'A reactor delivers 3.0 GW of thermal power. Calculate the mass converted into energy each second, in units of 10⁻⁸ kg. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '3.333', '10⁻⁸ kg', false, NULL, false, NULL, 'Δm per second = P/c² = 3.0 × 10⁹ ÷ (3.00 × 10⁸)² = 3.33 × 10⁻⁸ kg. Mark scheme (3 marks). C1: E = Pt. C1: Δm = E/c². A1: Δm = 3.33 × 10⁻⁸ kg.', 3, NULL, NULL),
('2c421a53-1941-590c-81d6-6ccd04b73661', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 42, 42, 'The Sun radiates 3.85 × 10²⁶ W and has a mass of 2.0 × 10³⁰ kg. (a) Calculate the mass it loses each second. (b) Calculate the mass lost in 1.0 × 10¹⁰ years (1 year = 3.16 × 10⁷ s). (c) Calculate this as a fraction of the Sun''s mass. Give only the answer to (c). Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '6.759e-4', NULL, false, NULL, false, NULL, '(a) 3.85 × 10²⁶ ÷ (3.00 × 10⁸)² = 4.278 × 10⁹ kg s⁻¹. (b) 4.278 × 10⁹ × 1.0 × 10¹⁰ × 3.16 × 10⁷ = 1.352 × 10²⁷ kg. (c) 1.352 × 10²⁷ ÷ 2.0 × 10³⁰ = 6.76 × 10⁻⁴. Mark scheme (5 marks). C1: Δm/t = P/c². C1: total time. M1: ratio. C1: value. A1: fraction = 6.76 × 10⁻⁴.', 5, NULL, NULL),
('ac0650aa-37ed-5b4f-aa81-a69fc24057c4', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 43, 43, 'An electron and a positron, each with negligible kinetic energy, annihilate into two photons. (a) Explain why two photons are produced, not one. (b) Calculate the energy of each photon in MeV. (c) Calculate the wavelength of each photon. Give only the answer to (b). Take mₑ = 9.11 × 10⁻³¹ kg and c = 3.00 × 10⁸ m s⁻¹. Take 1 MeV = 1.60 × 10⁻¹³ J.', NULL, 3, 'numeric'::answer_type, '0.5124', 'MeV', false, NULL, false, NULL, '(a) Total momentum is zero, so the photons must travel in opposite directions. (b) E = mₑc² = 9.11 × 10⁻³¹ × (3.00 × 10⁸)² = 8.199 × 10⁻¹⁴ J; in MeV: 8.199 × 10⁻¹⁴ ÷ 1.60 × 10⁻¹³ = 0.512. (c) λ = hc/E ≈ 2.4 × 10⁻¹² m. Mark scheme (6 marks). B1: momentum conservation. C1: E = mₑc² each. C1: value in J. C1: in MeV. C1: wavelength. A1: E = 0.512 MeV.', 6, NULL, NULL),
('ff850bf1-b165-5784-9ad3-3742fb8b5b38', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 44, 44, 'A gamma photon of energy 3.0 MeV produces an electron–positron pair. (a) Calculate the rest energy of an electron in MeV. (b) Calculate the total kinetic energy of the pair. Take mₑ = 9.11 × 10⁻³¹ kg and c = 3.00 × 10⁸ m s⁻¹. Take 1 MeV = 1.60 × 10⁻¹³ J.', NULL, 3, 'numeric'::answer_type, '1.975', 'MeV', false, NULL, false, NULL, '(a) mₑc² = 9.11 × 10⁻³¹ × (3.00 × 10⁸)² ÷ 1.60 × 10⁻¹³ = 0.5124 MeV. (b) Ek = 3.0 − 2 × 0.5124 = 1.98 MeV. Mark scheme (5 marks). C1: rest energy. M1: two rest energies. C1: subtraction. C1: value. A1: Ek = 1.98 MeV.', 5, NULL, NULL),
('22b3c9ec-0920-53bb-bd7b-45df6c0fa9c0', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 45, 45, 'A power station supplies 1.2 GW of electrical power with an efficiency of 35%. (a) Calculate the thermal power. (b) Calculate the energy released in one day. (c) Calculate the mass converted into energy each day, in kg. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '0.003291', 'kg', false, NULL, false, NULL, '(a) 1.2 × 10⁹ ÷ 0.35 = 3.429 × 10⁹ W. (b) E = 3.429 × 10⁹ × 86400 = 2.962 × 10¹⁴ J. (c) Δm = 2.962 × 10¹⁴ ÷ (3.00 × 10⁸)² = 0.00329 kg. Mark scheme (6 marks). C1: thermal power. C1: seconds in a day. C1: energy. M1: Δm = E/c². C1: value. A1: Δm = 0.00329 kg.', 6, NULL, NULL),
('7bad3ef3-f13e-5217-bf0e-cbd33e92dbc7', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 46, 46, 'In one fission, uranium-235 (235.0439 u) absorbs a neutron (1.0087 u) and produces barium-141 (140.9144 u), krypton-92 (91.9262 u) and three neutrons. (a) Calculate the mass defect in u. (b) Calculate the energy released in MeV, taking 1 u as 931.5 MeV.', NULL, 3, 'numeric'::answer_type, '173.2', 'MeV', false, NULL, false, NULL, '(a) Δm = (235.0439 + 1.0087) − (140.9144 + 91.9262 + 3 × 1.0087) = 0.1859 u. (b) E = 0.1859 × 931.5 = 173 MeV. Mark scheme (5 marks). C1: mass before. C1: mass after. M1: × 931.5. C1: value. A1: E = 173 MeV.', 5, NULL, NULL),
('e20ab14b-c5f9-5b7d-84dc-6850fc108ac4', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 47, 47, 'Deuterium (2.0141 u) and tritium (3.0160 u) fuse to give helium-4 (4.0026 u) and a neutron (1.0087 u). (a) Calculate the energy released per reaction in J. (b) Calculate the mass of fuel used per reaction in kg. (c) Calculate the energy released per kilogram of fuel, in units of 10¹⁴ J kg⁻¹. Take 1 u = 1.66 × 10⁻²⁷ kg and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '3.364', '10¹⁴ J kg⁻¹', false, NULL, false, NULL, '(a) Δm = 5.0301 − 5.0113 = 0.0188 u = 3.121 × 10⁻²⁹ kg; E = 3.121 × 10⁻²⁹ × (3.00 × 10⁸)² = 2.809 × 10⁻¹² J. (b) 5.0301 × 1.66 × 10⁻²⁷ = 8.350 × 10⁻²⁷ kg. (c) 2.809 × 10⁻¹² ÷ 8.350 × 10⁻²⁷ = 3.36 × 10¹⁴ J kg⁻¹. Mark scheme (6 marks). C1: mass defect. C1: E = Δmc². C1: fuel mass. M1: energy ÷ mass. C1: value. A1: E per kg = 3.36 × 10¹⁴ J kg⁻¹.', 6, NULL, NULL),
('c4218a0f-9402-51e5-bef9-49c177b20811', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 48, 48, 'Burning coal releases about 30 MJ per kg; fission of uranium-235 releases about 8.2 × 10¹³ J per kg. (a) Calculate (energy per kg from fission) ÷ (energy per kg from coal). (b) Explain the size of the ratio in terms of the energies involved.', NULL, 3, 'numeric'::answer_type, '2.733e6', NULL, false, NULL, false, NULL, '(a) 8.2 × 10¹³ ÷ 30 × 10⁶ = 2.73 × 10⁶. (b) Each fission releases about 200 MeV; each chemical bond change releases only a few eV. Mark scheme (5 marks). C1: same units. M1: ratio. C1: value. B1: MeV compared with eV. A1: ratio = 2.73 × 10⁶.', 5, NULL, NULL),
('79e33daf-3b05-51f5-9cd2-62c14f01dc76', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 49, 49, 'A 1.0 kg mass is lifted 10 m (g = 9.81 m s⁻²). (a) Calculate the gain in gravitational potential energy. (b) Calculate the corresponding increase in the mass of the Earth–mass system. Give only the answer to (b), in units of 10⁻¹⁵ kg. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '1.09', '10⁻¹⁵ kg', false, NULL, false, NULL, '(a) ΔE = mgh = 1.0 × 9.81 × 10 = 98.1 J. (b) Δm = 98.1 ÷ (3.00 × 10⁸)² = 1.09 × 10⁻¹⁵ kg. Mark scheme (5 marks). C1: mgh. M1: Δm = ΔE/c². C1: substitution. C1: value. A1: Δm = 1.09 × 10⁻¹⁵ kg.', 5, NULL, NULL),
('7264d8f1-b035-596a-a179-ca0473bf4742', 'aae53119-5afd-4055-b81b-60e6244772d7', 'aa310305-acdb-4a66-9833-4fdfca276c71', 'a-level', '29.2', '9702 coursebook 29.2 · Mass and energy', 50, 50, 'An electron and a positron each have 1.0 MeV of kinetic energy when they meet head-on and annihilate into two photons of equal energy. (a) Calculate the rest energy of each particle in MeV. (b) Calculate the energy of each photon. (c) Calculate the photon wavelength in units of 10⁻¹³ m. Take mₑ = 9.11 × 10⁻³¹ kg, c = 3.00 × 10⁸ m s⁻¹ and h = 6.63 × 10⁻³⁴ J s. Take 1 MeV = 1.60 × 10⁻¹³ J.', NULL, 3, 'numeric'::answer_type, '8.219', '10⁻¹³ m', false, NULL, false, NULL, '(a) mₑc² = 9.11 × 10⁻³¹ × (3.00 × 10⁸)² ÷ 1.60 × 10⁻¹³ = 0.5124 MeV. (b) Each photon: 0.5124 + 1.0 = 1.512 MeV. (c) λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (1.512 × 1.60 × 10⁻¹³) = 8.22 × 10⁻¹³ m. Mark scheme (6 marks). C1: rest energy. M1: total energy shared. C1: photon energy. C1: MeV to J. C1: λ = hc/E. A1: λ = 8.22 × 10⁻¹³ m.', 6, NULL, NULL)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('af70d63b-bc64-501d-8c38-f9e3136eec40', 'bb89358f-c802-5cf3-bbd4-93ae64f94e8f', 'Energy is always lost in reactions', 'A', false, 0),
('1f77c616-4b8e-596c-9f78-952c3b62b785', 'bb89358f-c802-5cf3-bbd4-93ae64f94e8f', 'Mass can only be destroyed in nuclear reactions', 'B', false, 1),
('bf708479-d3e2-51c5-a4a0-e3d5c68ad58a', 'bb89358f-c802-5cf3-bbd4-93ae64f94e8f', 'Mass and energy are equivalent: a change in energy goes with a change in mass', 'C', true, 2),
('4de6e4cc-6d6f-5bea-93bf-04c15cbed98e', 'bb89358f-c802-5cf3-bbd4-93ae64f94e8f', 'Energy travels at the speed of light', 'D', false, 3),
('1e968f26-95ce-5064-b98a-1bf5f52a8a02', 'cd533658-5865-5458-a631-0a03971dd03a', 'One twelfth of the mass of a carbon-12 atom', 'A', true, 0),
('f933d569-3109-5e43-a6f1-9776011b67a6', 'cd533658-5865-5458-a631-0a03971dd03a', 'The mass of a proton', 'B', false, 1),
('0afc6c4c-8030-5e5a-bc2d-f3376def5bd3', 'cd533658-5865-5458-a631-0a03971dd03a', 'The mass of a hydrogen atom', 'C', false, 2),
('8171057f-9c0a-5e4e-9d68-f146f7330ec6', 'cd533658-5865-5458-a631-0a03971dd03a', 'One sixteenth of the mass of an oxygen-16 atom', 'D', false, 3),
('c0ad9dcd-e559-50d4-b009-caadbcdf9ddb', '4495fe63-85e4-5689-bc7e-b763f68d94d5', 'It increases', 'A', false, 0),
('ef27b701-da37-57e8-baea-6688e48c7de5', '4495fe63-85e4-5689-bc7e-b763f68d94d5', 'It stays exactly the same', 'B', false, 1),
('11d5f7f2-038b-5ad6-baf3-207949d1df11', '4495fe63-85e4-5689-bc7e-b763f68d94d5', 'It becomes zero', 'C', false, 2),
('d6985421-447e-5d31-a762-86c7f7258304', '4495fe63-85e4-5689-bc7e-b763f68d94d5', 'It decreases, because energy is released', 'D', true, 3),
('a5b7f549-ac9f-5c10-b525-1cdfbc16227b', '6e531e08-225e-546c-9586-b157d83d401e', 'Mass only', 'A', false, 0),
('96e61840-08be-5426-833a-40b38eef440e', '6e531e08-225e-546c-9586-b157d83d401e', 'Energy', 'B', true, 1),
('6ac1aed0-12bf-5dee-b530-57f392971f10', '6e531e08-225e-546c-9586-b157d83d401e', 'Charge', 'C', false, 2),
('adc82572-37f8-5057-aac3-e44e79aeb0f8', '6e531e08-225e-546c-9586-b157d83d401e', 'Potential difference', 'D', false, 3),
('2b263d90-eedd-5c53-96d2-0a45dc92979d', '9c3cbe61-e8f0-5fce-8130-c13cde697ca8', 'Chemical reactions do not involve energy', 'A', false, 0),
('819495d2-b970-5acd-9362-46846695094e', '9c3cbe61-e8f0-5fce-8130-c13cde697ca8', 'Mass is only equivalent to energy in nuclei', 'B', false, 1),
('950605d4-0709-58d8-8bee-74128a186527', '9c3cbe61-e8f0-5fce-8130-c13cde697ca8', 'The energy changes are so small that Δm = ΔE/c² is far too tiny to measure', 'C', true, 2),
('45f10c05-7492-5090-ab36-afff8f4d9030', '9c3cbe61-e8f0-5fce-8130-c13cde697ca8', 'Chemical energy has no mass', 'D', false, 3),
('4caf52ac-59b5-5e93-a7ca-c1e3c1684613', 'f86fa476-9485-517b-a4d7-6f85c211e757', 'Total mass–energy', 'A', true, 0),
('82078f78-a4db-5171-bee8-53080b78e967', 'f86fa476-9485-517b-a4d7-6f85c211e757', 'Total rest mass', 'B', false, 1),
('d77df475-cd76-5a13-8de7-3b6595290bd8', 'f86fa476-9485-517b-a4d7-6f85c211e757', 'Total kinetic energy', 'C', false, 2),
('caf35b28-6d0d-5c36-aa3a-13e3e8767823', 'f86fa476-9485-517b-a4d7-6f85c211e757', 'The number of protons', 'D', false, 3),
('a36414c8-8c45-54ed-90d6-18d1c7aacb20', '12d4d73a-8bcd-56ab-b7b3-281414c40682', '511 MeV', 'A', false, 0),
('e5ca86a4-9f91-5f2c-9939-9ac511712212', '12d4d73a-8bcd-56ab-b7b3-281414c40682', '0.51 eV', 'B', false, 1),
('a9c4e138-b475-5137-91c2-309742f8fa83', '12d4d73a-8bcd-56ab-b7b3-281414c40682', '938 MeV', 'C', false, 2),
('dcad17d2-8143-5d42-a304-c94bd8061dcd', '12d4d73a-8bcd-56ab-b7b3-281414c40682', '0.51 MeV', 'D', true, 3),
('9818aa71-9f36-5520-92ef-aa4c1e136204', 'a0228684-9d05-5f59-a9b8-28403ff79e76', 'Energy must be supplied', 'A', false, 0),
('7e661659-84bd-59e6-b230-5d5b5f674548', 'a0228684-9d05-5f59-a9b8-28403ff79e76', 'Energy is released, mostly as kinetic energy of the products', 'B', true, 1),
('cc6f2f6a-2f30-566e-b58c-4a41fbba4bae', 'a0228684-9d05-5f59-a9b8-28403ff79e76', 'Mass has been destroyed without trace', 'C', false, 2),
('8c326537-b7dd-5a16-855c-da7a499b551c', 'a0228684-9d05-5f59-a9b8-28403ff79e76', 'Charge has been lost', 'D', false, 3),
('867f3f48-cdc4-506a-b167-f50ef466d2a9', 'bd979c38-abd9-568b-9a55-0c7247f12253', 'Some neutrons are destroyed', 'A', false, 0),
('fedc0cc0-49a8-5a38-8252-17d5523a874e', 'bd979c38-abd9-568b-9a55-0c7247f12253', 'Mass is converted into charge', 'B', false, 1),
('a0d2d304-a2c4-5560-978a-7fdd123f2460', 'bd979c38-abd9-568b-9a55-0c7247f12253', 'The products are more tightly bound, and the extra binding energy is released', 'C', true, 2),
('a1391454-019a-550b-a8ba-d58315f04af7', 'bd979c38-abd9-568b-9a55-0c7247f12253', 'The fragments are moving, which reduces their mass', 'D', false, 3),
('9fb23a48-5811-551f-83f9-985557f68f42', '5c6a8453-9b55-59f0-b36f-645722d94c9b', 'It increases by a tiny amount equal to the energy supplied ÷ c²', 'A', true, 0),
('7988b3c1-6fad-53b5-bbaf-86cb8f20080d', '5c6a8453-9b55-59f0-b36f-645722d94c9b', 'It stays exactly the same', 'B', false, 1),
('c93ad8a3-7622-5300-a2f7-ff6424cf29d5', '5c6a8453-9b55-59f0-b36f-645722d94c9b', 'It decreases by energy ÷ c²', 'C', false, 2),
('343efa6b-8af9-5c85-896e-80f8585f9046', '5c6a8453-9b55-59f0-b36f-645722d94c9b', 'It increases by about 1%', 'D', false, 3),
('9eef1cf2-f682-5b3f-b617-d8b864c46943', '27fda783-d896-50bc-8582-b0fce3d70c6c', 'Nuclear fuels are denser', 'A', false, 0),
('ccfc77bf-2de3-5138-b015-36570d2369c8', '27fda783-d896-50bc-8582-b0fce3d70c6c', 'Chemical reactions are slower', 'B', false, 1),
('a2c2c6f9-c1d8-5aad-b027-9343dcd41d25', '27fda783-d896-50bc-8582-b0fce3d70c6c', 'Nuclear reactions destroy all of the mass', 'C', false, 2),
('4dc6dbd7-eaba-565f-879b-78088fe12c43', '27fda783-d896-50bc-8582-b0fce3d70c6c', 'Nuclear binding energies are millions of electronvolts per nucleon, compared with a few electronvolts per bond', 'D', true, 3),
('51ba1b12-bff5-5f48-a560-a61f912d48af', '5cd6c069-1c6c-50d7-9d35-77059d13c7c2', 'An α-particle slowing down in air', 'A', false, 0),
('84222b7a-cc37-5b89-b090-95d0b287090d', '5cd6c069-1c6c-50d7-9d35-77059d13c7c2', 'A γ-ray photon producing an electron–positron pair', 'B', true, 1),
('11556186-b6e4-5f2b-aae2-eb4c56a3987c', '5cd6c069-1c6c-50d7-9d35-77059d13c7c2', 'A nucleus emitting a β-particle', 'C', false, 2),
('c80e1b4f-d13c-5bed-a46a-1497875261bd', '5cd6c069-1c6c-50d7-9d35-77059d13c7c2', 'An electron and positron annihilating', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('9c80c9b5-2183-5ab7-8c73-c7bec518864e', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 7, 7, 'In an α decay the mass decreases by 0.0060 u. Taking 1 u as equivalent to 931.5 MeV, calculate the energy released.', NULL, 1, 'numeric'::answer_type, '5.589', 'MeV', false, NULL, false, NULL, 'E = 0.0060 × 931.5 = 5.59 MeV. Mark scheme (2 marks). C1: × 931.5. A1: E = 5.59 MeV.', 2, NULL, NULL),
('a5db4df9-c40a-574b-8b59-77ca01976b00', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 8, 8, 'Where does the energy released in an α decay mainly go?', NULL, 1, 'multiple_choice'::answer_type, 'Into the kinetic energy of the α-particle and the recoiling daughter nucleus', NULL, false, NULL, false, NULL, 'The mass loss Δm × c² becomes kinetic energy (and sometimes a γ-ray). Mark scheme (1 mark). B1: C (Into the kinetic energy of the α-particle and the recoiling daughter nucleus).', 1, NULL, NULL),
('b374d62e-7800-59b7-9186-b23d3acffd84', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 9, 9, 'An α-particle is emitted with 4.8 MeV of kinetic energy. Express this energy in units of 10⁻¹³ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '7.68', '10⁻¹³ J', false, NULL, false, NULL, 'E = 4.8 × 10⁶ × 1.60 × 10⁻¹⁹ = 7.68 × 10⁻¹³ J. Mark scheme (2 marks). C1: MeV to J. A1: E = 7.68 × 10⁻¹³ J.', 2, NULL, NULL),
('754022a4-145a-5bb3-9f03-45d6c7e64acd', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 10, 10, 'In an α decay, why does the α-particle receive most of the kinetic energy?', NULL, 1, 'multiple_choice'::answer_type, 'Momentum is shared equally and opposite, so the much lighter α-particle moves much faster', NULL, false, NULL, false, NULL, 'Equal momenta: Ek = p²/2m is largest for the smallest mass. Mark scheme (1 mark). B1: A (Momentum is shared equally and opposite, so the much lighter α-particle moves much faster).', 1, NULL, NULL),
('ca367d19-5a08-5014-81f3-c23e71420e0d', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 11, 11, 'An α-particle (mass 6.64 × 10⁻²⁷ kg) has 5.0 MeV of kinetic energy. Calculate its speed in units of 10⁷ m s⁻¹. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.552', '10⁷ m s⁻¹', false, NULL, false, NULL, 'Ek = 5.0 × 10⁶ × 1.60 × 10⁻¹⁹ = 8.0 × 10⁻¹³ J. v = √(2 × 8.0 × 10⁻¹³ ÷ 6.64 × 10⁻²⁷) = 1.55 × 10⁷ m s⁻¹. Mark scheme (2 marks). C1: ½mv² = Ek. A1: v = 1.55 × 10⁷ m s⁻¹.', 2, NULL, NULL),
('73bb0eb1-0657-542c-b2ce-c1c9826082bc', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 12, 12, 'Why do β-particles from one isotope have a continuous range of energies?', NULL, 1, 'multiple_choice'::answer_type, 'The energy released is shared between the β-particle and an (anti)neutrino', NULL, false, NULL, false, NULL, 'The sharing varies from decay to decay. Mark scheme (1 mark). B1: D (The energy released is shared between the β-particle and an (anti)neutrino).', 1, NULL, NULL),
('45e0ff8b-6325-523d-8e91-5fb978c21a61', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 13, 13, 'A free neutron decays, releasing 0.78 MeV. Express this energy in units of 10⁻¹³ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.248', '10⁻¹³ J', false, NULL, false, NULL, 'E = 0.78 × 10⁶ × 1.60 × 10⁻¹⁹ = 1.25 × 10⁻¹³ J. Mark scheme (2 marks). C1: MeV to J. A1: E = 1.25 × 10⁻¹³ J.', 2, NULL, NULL),
('14e4b75c-8d7f-50f0-b596-179265bad39d', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 14, 14, 'Why is a γ-ray often emitted just after an α or β decay?', NULL, 1, 'multiple_choice'::answer_type, 'The daughter nucleus is left in an excited state and drops to its ground state', NULL, false, NULL, false, NULL, 'Nuclei have energy levels; γ-photons carry away the excess. Mark scheme (1 mark). B1: B (The daughter nucleus is left in an excited state and drops to its ground state).', 1, NULL, NULL),
('e5258f8a-c7e0-5f63-8769-93021fdac6d6', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 15, 15, 'Cobalt-60 emits γ-rays of energy 1.17 MeV. Calculate their wavelength in units of 10⁻¹² m. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.062', '10⁻¹² m', false, NULL, false, NULL, 'E = 1.17 × 10⁶ × 1.60 × 10⁻¹⁹ = 1.872 × 10⁻¹³ J. λ = hc/E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 1.872 × 10⁻¹³ = 1.06 × 10⁻¹² m. Mark scheme (2 marks). C1: λ = hc/E. A1: λ = 1.06 × 10⁻¹² m.', 2, NULL, NULL),
('3b249f18-6b86-5fcf-b7fe-ce8e2722ed11', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 16, 16, 'A decay can happen spontaneously only if', NULL, 1, 'multiple_choice'::answer_type, 'the total mass of the products is less than the mass of the parent', NULL, false, NULL, false, NULL, 'The mass decrease supplies the energy released. Mark scheme (1 mark). B1: C (the total mass of the products is less than the mass of the parent).', 1, NULL, NULL),
('223af9b9-5707-58fd-999e-800db7536f78', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 17, 17, 'Polonium-210 (209.9829 u) decays into lead-206 (205.9745 u) and an α-particle (4.0026 u). Calculate the mass decrease in u.', NULL, 1, 'numeric'::answer_type, '0.0058', 'u', false, NULL, false, NULL, 'Δm = 209.9829 − (205.9745 + 4.0026) = 0.0058 u. Mark scheme (2 marks). C1: parent − products. A1: Δm = 0.0058 u.', 2, NULL, NULL),
('4d9890c7-25cc-5ec4-9888-33219c76cfb4', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 18, 18, 'How does the total rest mass of the products of a decay compare with the rest mass of the parent?', NULL, 1, 'multiple_choice'::answer_type, 'It is smaller', NULL, false, NULL, false, NULL, 'Energy is released, so Δm = E/c² is lost. Mark scheme (1 mark). B1: A (It is smaller).', 1, NULL, NULL),
('d185e83d-f89f-5fda-a2c4-a475369ca325', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 19, 19, 'The decay of polonium-210 has a mass decrease of 0.0058 u. Taking 1 u as 931.5 MeV, calculate the energy released.', NULL, 1, 'numeric'::answer_type, '5.403', 'MeV', false, NULL, false, NULL, 'E = 0.0058 × 931.5 = 5.40 MeV. Mark scheme (2 marks). C1: × 931.5. A1: E = 5.40 MeV.', 2, NULL, NULL),
('90278a9b-1030-5031-b80b-933b5b7bfbc1', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 20, 20, 'Which quantity is shared equally (in size) between an α-particle and the daughter nucleus when a stationary nucleus decays?', NULL, 1, 'multiple_choice'::answer_type, 'Momentum', NULL, false, NULL, false, NULL, 'The parent was at rest, so the momenta are equal and opposite. Mark scheme (1 mark). B1: D (Momentum).', 1, NULL, NULL),
('4f389b6a-afeb-549c-bd44-0b4760fdb07c', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 21, 21, 'A source undergoes 3.7 × 10¹⁰ decays per second, each releasing 2.0 MeV that is absorbed. Calculate the heating power in mW. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '11.84 mW', 'mW', false, NULL, false, NULL, 'P = 3.7 × 10¹⁰ × 2.0 × 10⁶ × 1.60 × 10⁻¹⁹ = 0.01184 W. In mW: 0.01184 × 10³ = 11.8. Mark scheme (2 marks). C1: power = decays per second × energy. A1: P = 11.8 mW.', 2, NULL, NULL),
('30fdb236-cf27-59d7-a500-94afa3a9cb18', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 22, 22, 'In an α decay the α-particle has nucleon number 4 and the daughter nucleon number 222. Calculate (kinetic energy of the α-particle) ÷ (kinetic energy of the daughter).', NULL, 1, 'numeric'::answer_type, '55.5', NULL, false, NULL, false, NULL, 'Equal momenta and Ek = p²/2m, so the ratio = 222 ÷ 4 = 55.5. Mark scheme (2 marks). C1: Ek ∝ 1/m for equal p. A1: ratio = 55.5.', 2, NULL, NULL),
('b00fcb95-7ccc-52d9-929f-b15eeae66f33', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 23, 23, 'The β-particles from tritium have a maximum energy of 0.0186 MeV. Express this in keV.', NULL, 1, 'numeric'::answer_type, '18.6', 'keV', false, NULL, false, NULL, 'E = 0.0186 × 10³ = 18.6 keV. Mark scheme (1 mark). A1: E = 18.6 keV.', 1, NULL, NULL),
('99c01c52-f4dd-550c-8882-4f335a4a493f', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 24, 24, 'Radium-226 decays to radon-222 by α emission, releasing 4.87 MeV. Calculate the kinetic energy of the α-particle, assuming the radium was at rest.', NULL, 2, 'numeric'::answer_type, '4.784', 'MeV', false, NULL, false, NULL, 'The α-particle takes the fraction 222/226 of the energy: Ek = 4.87 × 222 ÷ 226 = 4.78 MeV. Mark scheme (3 marks). M1: momentum shared equally. C1: fraction 222/226. A1: Ek = 4.78 MeV.', 3, NULL, NULL),
('cab95651-fe60-5a62-96c2-7ce8eb0c050d', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 25, 25, 'An α-particle (4 u) leaves a nucleus at rest with a speed of 1.5 × 10⁷ m s⁻¹. The daughter has a mass of 222 u. Calculate the recoil speed of the daughter.', NULL, 2, 'numeric'::answer_type, '2.703e5', 'm s⁻¹', false, NULL, false, NULL, 'Momentum: 222 × v = 4 × 1.5 × 10⁷, so v = 4 × 1.5 × 10⁷ ÷ 222 = 2.70 × 10⁵ m s⁻¹. Mark scheme (4 marks). M1: total momentum zero. C1: equation. C1: value. A1: v = 2.70 × 10⁵ m s⁻¹.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 200" role="img" aria-labelledby="fgf3f87246-t fgf3f87246-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf3f87246-t">Recoil in α decay</title><desc id="fgf3f87246-d">Before: a nucleus at rest. After: the daughter nucleus of mass 222 u recoils with unknown speed v while the α-particle of mass 4 u moves the other way at 1.5 × 10⁷ m s⁻¹.</desc><text x="210" y="18" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">before</text><circle cx="210" cy="50" r="18" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="238" y="50" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">parent at rest</text><line x1="20" y1="86" x2="400" y2="86" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><text x="210" y="104" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">after</text><circle cx="170" cy="146" r="16" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="250" cy="146" r="7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="148" y1="146" x2="114.3" y2="146" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="108,146 116.2,142.2 116.2,149.8" style="fill:currentColor;stroke:none"/><line x1="262" y1="146" x2="335.7" y2="146" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="342,146 333.8,149.8 333.8,142.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="170" y="176" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">daughter, 222 u</text><text x="250" y="176" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">α, 4 u</text><text x="128" y="132" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">v = ?</text><text x="302" y="132" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">1.5 × 10⁷ m s⁻¹</text></svg>', 'Before: a nucleus at rest. After: the daughter nucleus of mass 222 u recoils with unknown speed v while the α-particle of mass 4 u moves the other way at 1.5 × 10⁷ m s⁻¹.'),
('65eca01f-6864-56b2-b1ee-532f65ea7fef', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 26, 26, 'Why do α-particles from one isotope all have the same energy, while β-particles have a spread of energies?', NULL, 2, 'multiple_choice'::answer_type, 'α decay produces two bodies sharing momentum in a fixed way; β decay produces three bodies (including a neutrino)', NULL, false, NULL, false, NULL, 'Two-body decay fixes the energies; three-body decay allows any share. Mark scheme (3 marks). C1: α two-body. C1: β three-body with neutrino. A1: B (α decay produces two bodies sharing momentum in a fixed way; β decay produces three bodies (including a neutrino)).', 3, NULL, NULL),
('7f438219-fa97-5915-b98c-527414c7369b', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 27, 27, 'Carbon-14 β decay releases 0.156 MeV. What is the greatest possible kinetic energy of the emitted electron, in units of 10⁻¹⁴ J? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '2.496', '10⁻¹⁴ J', false, NULL, false, NULL, 'When the antineutrino gets almost nothing, Ek(max) ≈ 0.156 × 10⁶ × 1.60 × 10⁻¹⁹ = 2.50 × 10⁻¹⁴ J. Mark scheme (3 marks). M1: maximum when neutrino energy ≈ 0. C1: MeV to J. A1: Ek(max) = 2.50 × 10⁻¹⁴ J.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgcb3aebf2-t fgcb3aebf2-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgcb3aebf2-t">β-particle energy spectrum</title><desc id="fgcb3aebf2-d">Graph of the relative number of β-particles from carbon-14 against their kinetic energy: a continuous curve from zero up to a maximum of 0.156 MeV.</desc><line x1="33" y1="34" x2="33" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="130" y1="34" x2="130" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="226.9" y1="34" x2="226.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="323.8" y1="34" x2="323.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="155.3" x2="382" y2="155.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="68.7" x2="382" y2="68.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="33" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="33,24 36,30.3 30.1,30.3" style="fill:currentColor;stroke:none"/><line x1="33" y1="242" x2="33" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="33" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="130" y1="242" x2="130" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="130" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.05</text><line x1="226.9" y1="242" x2="226.9" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="226.9" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.10</text><line x1="323.8" y1="242" x2="323.8" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="323.8" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.15</text><line x1="29" y1="242" x2="33" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="29" y1="155.3" x2="33" y2="155.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="155.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.5</text><line x1="29" y1="68.7" x2="33" y2="68.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="68.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.0</text><text x="207.5" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">kinetic energy / MeV</text><text x="29" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">number of β-particles (relative)</text><line x1="335.5" y1="34" x2="335.5" y2="242" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><text x="339.5" y="42" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">0.156</text><polyline points="33,166 38.1,142.5 43.1,126 48.2,113.7 53.2,104.2 58.2,96.9 63.3,91.2 68.3,87 73.4,84 78.4,81.9 83.4,80.8 88.5,80.4 93.5,80.7 98.6,81.6 103.6,83 108.6,84.9 113.7,87.3 118.7,90 123.8,93.1 128.8,96.4 133.9,100 138.9,103.9 143.9,108 149,112.2 154,116.6 159.1,121.2 164.1,125.8 169.1,130.6 174.2,135.4 179.2,140.2 184.3,145.1 189.3,150 194.3,155 199.4,159.9 204.4,164.7 209.5,169.5 214.5,174.3 219.5,179 224.6,183.6 229.6,188.1 234.7,192.5 239.7,196.8 244.7,201 249.8,205 254.8,208.8 259.9,212.5 264.9,216.1 269.9,219.4 275,222.5 280,225.5 285.1,228.2 290.1,230.7 295.1,233 300.2,235 305.2,236.8 310.3,238.4 315.3,239.7 320.4,240.7 325.4,241.4 330.4,241.9 335.5,242" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Graph of the relative number of β-particles from carbon-14 against their kinetic energy: a continuous curve from zero up to a maximum of 0.156 MeV.'),
('4393b214-f126-5e01-ba1b-105a3b685b2b', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 28, 28, 'The atomic masses of carbon-14 and nitrogen-14 are 14.003242 u and 14.003074 u. Using atomic masses for β⁻ decay, calculate the energy released, taking 1 u as 931.5 MeV.', NULL, 2, 'numeric'::answer_type, '0.1565', 'MeV', false, NULL, false, NULL, 'Δm = 14.003242 − 14.003074 = 0.000168 u. E = 0.000168 × 931.5 = 0.156 MeV. Mark scheme (3 marks). C1: mass difference. C1: × 931.5. A1: E = 0.156 MeV.', 3, NULL, NULL),
('b1f53c76-1251-5b21-9953-4e7295ed8e42', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 29, 29, 'A plutonium-238 power source has an activity of 1.0 × 10¹⁵ Bq, and each decay releases 5.5 MeV. Calculate the heat output in W. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '880', 'W', false, NULL, false, NULL, 'P = 1.0 × 10¹⁵ × 5.5 × 10⁶ × 1.60 × 10⁻¹⁹ = 880 W. Mark scheme (3 marks). C1: energy per decay in J. C1: × decays per second. A1: P = 880 W.', 3, NULL, NULL),
('b8ef5f11-7e78-53a4-81ba-432bfb542871', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 30, 30, 'After an α decay, a daughter nucleus emits a γ-ray of fixed energy. What does this show?', NULL, 2, 'multiple_choice'::answer_type, 'Nuclei have discrete energy levels', NULL, false, NULL, false, NULL, 'Fixed γ energies match differences between nuclear levels. Mark scheme (3 marks). C1: discrete γ energy. C1: nuclear energy levels. A1: C (Nuclei have discrete energy levels).', 3, NULL, NULL),
('2d59f854-ac1f-5445-8c06-60c4fe5351e0', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 31, 31, 'A radon sample undergoes 1.0 × 10¹² decays, each releasing 5.6 MeV. Calculate the total energy released. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '0.896', 'J', false, NULL, false, NULL, 'E = 1.0 × 10¹² × 5.6 × 10⁶ × 1.60 × 10⁻¹⁹ = 0.896 J. Mark scheme (3 marks). C1: energy per decay. C1: × number of decays. A1: E = 0.896 J.', 3, NULL, NULL),
('e983f66a-0930-56cb-aa1d-80b512f62cc8', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 32, 32, 'Caesium-137 sources emit γ-rays of 0.662 MeV. Calculate their frequency in units of 10²⁰ Hz. Take e = 1.60 × 10⁻¹⁹ C and h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '1.598', '10²⁰ Hz', false, NULL, false, NULL, 'E = 0.662 × 10⁶ × 1.60 × 10⁻¹⁹ = 1.059 × 10⁻¹³ J. f = E/h = 1.059 × 10⁻¹³ ÷ 6.63 × 10⁻³⁴ = 1.60 × 10²⁰ Hz. Mark scheme (3 marks). C1: MeV to J. C1: f = E/h. A1: f = 1.60 × 10²⁰ Hz.', 3, NULL, NULL),
('7cf2861c-a516-50de-89f8-3fd912fdac49', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 33, 33, 'In β⁻ decay, the energy released is shared between which particles?', NULL, 2, 'multiple_choice'::answer_type, 'The electron, the antineutrino and (a little) the recoiling nucleus', NULL, false, NULL, false, NULL, 'Three bodies share energy and momentum. Mark scheme (3 marks). C1: electron and antineutrino. C1: recoil small. A1: A (The electron, the antineutrino and (a little) the recoiling nucleus).', 3, NULL, NULL),
('e2e2fc1f-ba88-57a1-9b20-cc1d8b36273e', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 34, 34, 'An α-particle of 5.0 MeV is stopped in air, losing on average 35 eV for each ion pair it produces. How many ion pairs does it produce?', NULL, 2, 'numeric'::answer_type, '1.429e5', NULL, false, NULL, false, NULL, 'N = 5.0 × 10⁶ ÷ 35 = 1.43 × 10⁵. Mark scheme (4 marks). C1: MeV to eV. C1: energy ÷ energy per pair. C1: value. A1: N = 1.43 × 10⁵.', 4, NULL, NULL),
('f0a03fda-3868-5a30-a2ae-cefad82e4073', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 35, 35, 'An α source of activity 2.0 × 10⁹ Bq emits 5.0 MeV α-particles, all absorbed in its casing. Calculate the heating power in mW. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '1.6 mW', 'mW', false, NULL, false, NULL, 'P = 2.0 × 10⁹ × 5.0 × 10⁶ × 1.60 × 10⁻¹⁹ = 0.001600 W. In mW: 0.001600 × 10³ = 1.60. Mark scheme (3 marks). C1: energy per decay. C1: power. A1: P = 1.6 mW.', 3, NULL, NULL),
('54a5a971-5d05-5a08-b294-a7e695f0a095', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 36, 36, 'Why is the kinetic energy of the recoiling daughter in α decay usually ignored?', NULL, 2, 'multiple_choice'::answer_type, 'Its large mass means it takes only a few per cent of the energy', NULL, false, NULL, false, NULL, 'Ek(daughter)/Ek(α) = mα/m(daughter). Mark scheme (3 marks). C1: equal momenta. C1: Ek inversely proportional to mass. A1: D (Its large mass means it takes only a few per cent of the energy).', 3, NULL, NULL),
('1b87915f-c3d9-556a-a4a3-0e8b276187d8', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 37, 37, 'In an α decay the α-particle (4 u) gets 4.78 MeV and the daughter has mass 222 u. Calculate the kinetic energy of the daughter in keV.', NULL, 2, 'numeric'::answer_type, '86.13', 'keV', false, NULL, false, NULL, 'Ek(daughter) = 4.78 × 4 ÷ 222 = 0.08613 MeV. In keV: 0.08613 × 10³ = 86.1. Mark scheme (3 marks). C1: Ek ∝ 1/m. C1: MeV to keV. A1: Ek = 86.1 keV.', 3, NULL, NULL),
('09018d45-1843-5fb7-ad24-6b3e2aeca02b', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 38, 38, 'A positron from β⁺ decay annihilates with an electron, both nearly at rest. The rest energy of each is 0.511 MeV. Calculate the total γ-ray energy produced.', NULL, 2, 'numeric'::answer_type, '1.022', 'MeV', false, NULL, false, NULL, 'E = 2 × 0.511 = 1.022 MeV. Mark scheme (3 marks). C1: two rest energies. C1: total. A1: E = 1.022 MeV.', 3, NULL, NULL),
('7bd4552b-b1f1-5af7-aca9-e9b9104cbca2', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 39, 39, 'Which type of decay causes the largest decrease in the mass of the nucleus?', NULL, 2, 'multiple_choice'::answer_type, 'α decay', NULL, false, NULL, false, NULL, 'α decay removes 4 nucleons; β and γ change the mass only slightly. Mark scheme (3 marks). C1: α removes 4 u. C1: others small. A1: B (α decay).', 3, NULL, NULL),
('815794e3-ceab-5c29-bee9-d38556fad769', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 40, 40, 'A free neutron (1.008665 u) decays into a proton (1.007276 u) and an electron (0.000549 u). Taking 1 u as 931.5 MeV, calculate the energy released.', NULL, 2, 'numeric'::answer_type, '0.7825', 'MeV', false, NULL, false, NULL, 'Δm = 1.008665 − 1.007276 − 0.000549 = 8.400 × 10⁻⁴ u. E = 8.400 × 10⁻⁴ × 931.5 = 0.782 MeV. Mark scheme (3 marks). C1: mass difference. C1: × 931.5. A1: E = 0.782 MeV.', 3, NULL, NULL),
('6b060787-03b1-5478-9421-5b84dcf0e40d', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 41, 41, 'Americium-241 at rest decays to neptunium-237 by α emission. Calculate (speed of the α-particle) ÷ (speed of the neptunium nucleus).', NULL, 2, 'numeric'::answer_type, '59.25', NULL, false, NULL, false, NULL, 'Equal momenta: 4v(α) = 237v(Np), so the ratio = 237 ÷ 4 = 59.25. Mark scheme (4 marks). M1: momentum conservation. C1: masses in u. C1: ratio. A1: ratio = 59.25.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 200" role="img" aria-labelledby="fgd6c32100-t fgd6c32100-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgd6c32100-t">Americium-241 decay</title><desc id="fgd6c32100-d">Before: americium-241 at rest. After: the neptunium-237 nucleus and the α-particle move apart in opposite directions.</desc><text x="210" y="18" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">before</text><circle cx="210" cy="50" r="18" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="238" y="50" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">americium-241 at rest</text><line x1="20" y1="86" x2="400" y2="86" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><text x="210" y="104" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">after</text><circle cx="170" cy="146" r="16" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="250" cy="146" r="7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="148" y1="146" x2="114.3" y2="146" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="108,146 116.2,142.2 116.2,149.8" style="fill:currentColor;stroke:none"/><line x1="262" y1="146" x2="335.7" y2="146" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="342,146 333.8,149.8 333.8,142.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="170" y="176" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">neptunium-237</text><text x="250" y="176" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">α-particle</text></svg>', 'Before: americium-241 at rest. After: the neptunium-237 nucleus and the α-particle move apart in opposite directions.'),
('1a0ab092-36f2-51dd-ac5d-3bf4a65aa136', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 42, 42, 'A graph of the number of β-particles against their kinetic energy is drawn for one isotope. What shape is it?', NULL, 2, 'multiple_choice'::answer_type, 'A continuous curve from zero up to a maximum energy', NULL, false, NULL, false, NULL, 'The energy is shared with the antineutrino in varying amounts. Mark scheme (3 marks). C1: continuous. C1: maximum energy = Q. A1: C (A continuous curve from zero up to a maximum energy).', 3, NULL, NULL),
('dcb9d615-bf6c-591e-b568-a218668198b8', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 43, 43, 'Uranium-238 (238.0508 u) decays to thorium-234 (234.0436 u) by emitting an α-particle (4.0026 u). (a) Calculate the mass decrease in u. (b) Calculate the energy released in MeV, taking 1 u as 931.5 MeV. (c) Calculate the kinetic energy of the α-particle. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '4.213', 'MeV', false, NULL, false, NULL, '(a) Δm = 238.0508 − 234.0436 − 4.0026 = 0.0046 u. (b) E = 0.0046 × 931.5 = 4.285 MeV. (c) Ek(α) = 4.285 × 234 ÷ 238 = 4.21 MeV. Mark scheme (5 marks). C1: mass decrease. C1: energy. M1: share 234/238. C1: value. A1: Ek = 4.21 MeV.', 5, NULL, NULL),
('6b421207-e29a-5800-90ce-57b43ff6b67f', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 44, 44, 'Polonium-212 at rest decays to lead-208, emitting an α-particle of kinetic energy 6.0 MeV. (a) Calculate the kinetic energy of the lead nucleus in MeV. (b) Calculate the mass of the lead nucleus in kg (1 u = 1.66 × 10⁻²⁷ kg). (c) Calculate its recoil speed. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '3.27e5', 'm s⁻¹', false, NULL, false, NULL, '(a) Ek = 6.0 × 4 ÷ 208 = 0.1154 MeV = 1.846 × 10⁻¹⁴ J. (b) m = 208 × 1.66 × 10⁻²⁷ = 3.453 × 10⁻²⁵ kg. (c) v = √(2 × 1.846 × 10⁻¹⁴ ÷ 3.453 × 10⁻²⁵) = 3.27 × 10⁵ m s⁻¹. Mark scheme (6 marks). M1: Ek ∝ 1/m. C1: Ek of lead. C1: J conversion. C1: mass. C1: speed. A1: v = 3.27 × 10⁵ m s⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 200" role="img" aria-labelledby="fg5ff30f42-t fg5ff30f42-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg5ff30f42-t">Polonium-212 decay</title><desc id="fg5ff30f42-d">Before: polonium-212 at rest. After: the lead-208 nucleus recoils while the α-particle moves off with 6.0 MeV of kinetic energy.</desc><text x="210" y="18" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">before</text><circle cx="210" cy="50" r="18" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="238" y="50" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">polonium-212 at rest</text><line x1="20" y1="86" x2="400" y2="86" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><text x="210" y="104" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">after</text><circle cx="170" cy="146" r="16" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="250" cy="146" r="7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="148" y1="146" x2="114.3" y2="146" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="108,146 116.2,142.2 116.2,149.8" style="fill:currentColor;stroke:none"/><line x1="262" y1="146" x2="335.7" y2="146" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="342,146 333.8,149.8 333.8,142.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="170" y="176" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">lead-208</text><text x="250" y="176" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">α-particle</text><text x="302" y="132" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">6.0 MeV</text></svg>', 'Before: polonium-212 at rest. After: the lead-208 nucleus recoils while the α-particle moves off with 6.0 MeV of kinetic energy.'),
('16374b46-274c-5eae-8cba-39d67fa7a7d5', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 45, 45, 'A radioisotope power source contains plutonium-238 with an activity of 6.3 × 10¹⁴ Bq. Each decay releases 5.6 MeV, and 6.0% of the heat is turned into electrical energy. (a) Calculate the heat output. (b) Calculate the electrical power. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '33.87', 'W', false, NULL, false, NULL, '(a) P = 6.3 × 10¹⁴ × 5.6 × 10⁶ × 1.60 × 10⁻¹⁹ = 564.5 W. (b) 0.060 × 564.5 = 33.9 W. Mark scheme (5 marks). C1: energy per decay. C1: heat output. M1: × efficiency. C1: value. A1: P = 33.9 W.', 5, NULL, NULL),
('1788de6c-5ad3-5405-96a1-0066d5a59f9d', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 46, 46, 'Cobalt-60 β⁻ decays to an excited state of nickel-60, which emits γ-rays of 1.17 MeV and 1.33 MeV in turn. (a) Calculate the total γ energy per decay. (b) Calculate the wavelength of the 1.33 MeV γ-ray. Give only the answer to (b), in units of 10⁻¹³ m. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '9.347', '10⁻¹³ m', false, NULL, false, NULL, '(a) 1.17 + 1.33 = 2.50 MeV. (b) E = 1.33 × 10⁶ × 1.60 × 10⁻¹⁹ = 2.128 × 10⁻¹³ J; λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 2.128 × 10⁻¹³ = 9.35 × 10⁻¹³ m. Mark scheme (6 marks). C1: total. C1: MeV to J. M1: λ = hc/E. C1: substitution. C1: value. A1: λ = 9.35 × 10⁻¹³ m.', 6, NULL, NULL),
('409df550-856a-5daa-8ae4-8732b24028ec', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 47, 47, 'A radium source of activity 3.7 × 10¹⁰ Bq releases 4.87 MeV per decay, all absorbed by 50 g of water (specific heat capacity 4200 J kg⁻¹ K⁻¹). (a) Calculate the energy absorbed in one hour. (b) Calculate the temperature rise of the water. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '0.4942', 'K', false, NULL, false, NULL, '(a) E = 3.7 × 10¹⁰ × 4.87 × 10⁶ × 1.60 × 10⁻¹⁹ × 3600 = 103.8 J. (b) ΔT = 103.8 ÷ (0.050 × 4200) = 0.494 K. Mark scheme (5 marks). C1: energy per second. C1: × 3600. M1: ΔT = E/mc. C1: value. A1: ΔT = 0.494 K.', 5, NULL, NULL),
('20d18aea-15f0-53c6-b01a-e6ffa826f48c', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 48, 48, 'Fluorine-18 decays by β⁺ emission, releasing 0.63 MeV. The positron then annihilates with an electron, both effectively at rest (rest energy 0.511 MeV each). (a) Calculate the energy of each annihilation photon. (b) Calculate the total energy released per fluorine-18 decay, including the annihilation.', NULL, 3, 'numeric'::answer_type, '1.652', 'MeV', false, NULL, false, NULL, '(a) Each photon has 0.511 MeV. (b) Total = 0.63 + 2 × 0.511 = 1.652 MeV. Mark scheme (6 marks). B1: two photons of 0.511 MeV. C1: annihilation total 1.022 MeV. M1: add decay energy. C1: value. B1: both particles effectively at rest. A1: E = 1.652 MeV.', 6, NULL, NULL),
('466b4ea6-504d-57fc-930c-06a1bea7e598', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 49, 49, 'Tritium (atomic mass 3.016049 u) β⁻ decays to helium-3 (atomic mass 3.016029 u). (a) Calculate the mass decrease in u. (b) Calculate the energy released in keV, taking 1 u as 931.5 MeV.', NULL, 3, 'numeric'::answer_type, '18.63', 'keV', false, NULL, false, NULL, '(a) Δm = 3.016049 − 3.016029 = 0.000020 u. (b) E = 0.000020 × 931.5 × 10³ = 18.6 keV. Mark scheme (5 marks). C1: mass difference. M1: × 931.5. C1: MeV to keV. C1: value. A1: E = 18.6 keV.', 5, NULL, NULL),
('97241cf0-61c1-5a84-a88c-646f0b6ce3dc', 'aae53119-5afd-4055-b81b-60e6244772d7', '7dea064c-452c-45f6-955f-b7e078a6e859', 'a-level', '29.3', '9702 coursebook 29.3 · Energy released in radioactive decay', 50, 50, 'Radon-222 (222.0176 u) decays into polonium-218 (218.0090 u) and an α-particle (4.0026 u). (a) Calculate the energy released in MeV, taking 1 u as 931.5 MeV. (b) Calculate the kinetic energy of the α-particle. (c) Calculate its speed (α mass 6.64 × 10⁻²⁷ kg). Give only the answer to (c), in units of 10⁷ m s⁻¹. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1.626', '10⁷ m s⁻¹', false, NULL, false, NULL, '(a) Δm = 222.0176 − 218.0090 − 4.0026 = 0.0060 u; E = 0.0060 × 931.5 = 5.589 MeV. (b) Ek = 5.589 × 218 ÷ 222 = 5.488 MeV = 8.781 × 10⁻¹³ J. (c) v = √(2 × 8.781 × 10⁻¹³ ÷ 6.64 × 10⁻²⁷) = 1.63 × 10⁷ m s⁻¹. Mark scheme (6 marks). C1: mass decrease. C1: energy. C1: α share. C1: J conversion. C1: speed. A1: v = 1.63 × 10⁷ m s⁻¹.', 6, NULL, NULL)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('25a13385-30d5-5570-84e8-e644e464f87b', 'a5db4df9-c40a-574b-8b59-77ca01976b00', 'Into the mass of the α-particle', 'A', false, 0),
('35414587-e030-58d0-baab-00d786f5a3cc', 'a5db4df9-c40a-574b-8b59-77ca01976b00', 'Into heating the nucleus before decay', 'B', false, 1),
('e9e5de8d-e9d9-5bca-9c31-4c88b02f2221', 'a5db4df9-c40a-574b-8b59-77ca01976b00', 'Into the kinetic energy of the α-particle and the recoiling daughter nucleus', 'C', true, 2),
('af658c0d-f846-5751-a759-7342598be3ea', 'a5db4df9-c40a-574b-8b59-77ca01976b00', 'Into the electrons of the atom only', 'D', false, 3),
('3893f341-723a-5316-a284-808f93e1c967', '754022a4-145a-5bb3-9f03-45d6c7e64acd', 'Momentum is shared equally and opposite, so the much lighter α-particle moves much faster', 'A', true, 0),
('3650bd46-ccde-5e8c-b70c-24f6dbf842be', '754022a4-145a-5bb3-9f03-45d6c7e64acd', 'The daughter nucleus absorbs energy', 'B', false, 1),
('facc46e7-35a9-591d-8f39-751af572de55', '754022a4-145a-5bb3-9f03-45d6c7e64acd', 'α-particles are charged', 'C', false, 2),
('5a3250b7-244a-5ac4-9273-2135355ed53b', '754022a4-145a-5bb3-9f03-45d6c7e64acd', 'The daughter nucleus is always at rest', 'D', false, 3),
('8e7d8d29-587a-52d1-b9d0-5befb2ddde36', '73bb0eb1-0657-542c-b2ce-c1c9826082bc', 'Some β-particles are slowed by the nucleus', 'A', false, 0),
('c2927234-390c-5b3a-a3af-2c30c1bd3c21', '73bb0eb1-0657-542c-b2ce-c1c9826082bc', 'The nucleus has many energy levels', 'B', false, 1),
('0ccab606-dccd-51c7-94c0-50b170626783', '73bb0eb1-0657-542c-b2ce-c1c9826082bc', 'β-particles collide with each other', 'C', false, 2),
('cbcfa7f7-5b90-56a6-8c31-c9ced504ff51', '73bb0eb1-0657-542c-b2ce-c1c9826082bc', 'The energy released is shared between the β-particle and an (anti)neutrino', 'D', true, 3),
('b1fbb190-de30-52a5-9496-dd5d40dbcd86', '14e4b75c-8d7f-50f0-b596-179265bad39d', 'The parent nucleus emits it before decaying', 'A', false, 0),
('e1a4fff5-fa2c-53d0-abd5-78de4cd4f2c3', '14e4b75c-8d7f-50f0-b596-179265bad39d', 'The daughter nucleus is left in an excited state and drops to its ground state', 'B', true, 1),
('f412a791-0c8a-535d-a3de-4f042c38851e', '14e4b75c-8d7f-50f0-b596-179265bad39d', 'The α-particle emits it as it slows', 'C', false, 2),
('2edd08ac-5aa2-528c-b0f1-65da9b197a4a', '14e4b75c-8d7f-50f0-b596-179265bad39d', 'The electrons of the atom emit it', 'D', false, 3),
('29d6239e-9358-5cd1-bfcf-bde9a0524fd3', '3b249f18-6b86-5fcf-b7fe-ce8e2722ed11', 'the products are heavier than the parent', 'A', false, 0),
('6ad991f6-1fe1-514b-9684-84b7e464c0f2', '3b249f18-6b86-5fcf-b7fe-ce8e2722ed11', 'the parent is at a high temperature', 'B', false, 1),
('70e4105a-22df-5374-9c34-739ead6ebfae', '3b249f18-6b86-5fcf-b7fe-ce8e2722ed11', 'the total mass of the products is less than the mass of the parent', 'C', true, 2),
('9941d3e1-d72b-5e7e-aecd-ae826830e5fa', '3b249f18-6b86-5fcf-b7fe-ce8e2722ed11', 'energy is supplied from outside', 'D', false, 3),
('a43fc6e2-2808-5d63-a25a-83032493de4b', '4d9890c7-25cc-5ec4-9888-33219c76cfb4', 'It is smaller', 'A', true, 0),
('4cc9377d-b551-59e2-bab5-866363ad0aff', '4d9890c7-25cc-5ec4-9888-33219c76cfb4', 'It is larger', 'B', false, 1),
('b7c799e4-15be-545a-8026-f6badf85e484', '4d9890c7-25cc-5ec4-9888-33219c76cfb4', 'It is equal', 'C', false, 2),
('5ae88dca-1b0a-5429-8c55-25c11fe94138', '4d9890c7-25cc-5ec4-9888-33219c76cfb4', 'It can be larger or smaller', 'D', false, 3),
('9d5b9c0b-289b-5548-8e1f-e5f4f5f21c25', '90278a9b-1030-5031-b80b-933b5b7bfbc1', 'Kinetic energy', 'A', false, 0),
('68802845-1d67-539b-9c01-99f850b8814b', '90278a9b-1030-5031-b80b-933b5b7bfbc1', 'Speed', 'B', false, 1),
('5feb1aa5-8cf8-5798-a7ac-5c253e667014', '90278a9b-1030-5031-b80b-933b5b7bfbc1', 'Mass', 'C', false, 2),
('79e316ef-d2f4-5282-9229-28935490aef6', '90278a9b-1030-5031-b80b-933b5b7bfbc1', 'Momentum', 'D', true, 3),
('3661a80b-05fb-54d9-9451-bde5f2b6220a', '65eca01f-6864-56b2-b1ee-532f65ea7fef', 'β-particles lose energy in the nucleus', 'A', false, 0),
('5a6caaf5-a1f8-53c6-9f44-c43766a21024', '65eca01f-6864-56b2-b1ee-532f65ea7fef', 'α decay produces two bodies sharing momentum in a fixed way; β decay produces three bodies (including a neutrino)', 'B', true, 1),
('3ac2876a-be7f-5339-965a-2a9652805b19', '65eca01f-6864-56b2-b1ee-532f65ea7fef', 'α-particles are heavier so cannot lose energy', 'C', false, 2),
('442f2d8c-01a7-57cb-9370-8ee1adda1a79', '65eca01f-6864-56b2-b1ee-532f65ea7fef', 'β decay releases no fixed energy', 'D', false, 3),
('825384ef-da6c-54ab-acf2-1a717f1f331d', 'b8ef5f11-7e78-53a4-81ba-432bfb542871', 'The daughter is unstable to β decay', 'A', false, 0),
('79ec5151-ddd5-5e41-8306-eb80cd9cfc59', 'b8ef5f11-7e78-53a4-81ba-432bfb542871', 'Energy is not conserved in decay', 'B', false, 1),
('44f5eba1-6277-5fc2-a480-26b8b9b64f24', 'b8ef5f11-7e78-53a4-81ba-432bfb542871', 'Nuclei have discrete energy levels', 'C', true, 2),
('5ae23276-498b-5928-9c47-3e8f99262d7d', 'b8ef5f11-7e78-53a4-81ba-432bfb542871', 'The α-particle has a continuous spectrum', 'D', false, 3),
('10b3b0d8-5604-5df2-9084-cf8d0e73b4a6', '7cf2861c-a516-50de-89f8-3fd912fdac49', 'The electron, the antineutrino and (a little) the recoiling nucleus', 'A', true, 0),
('867b7729-0313-58ec-b639-0f3fdd4766ff', '7cf2861c-a516-50de-89f8-3fd912fdac49', 'The electron only', 'B', false, 1),
('17408fc5-a1d4-5007-b9cd-3753617d9a94', '7cf2861c-a516-50de-89f8-3fd912fdac49', 'The electron and a neutrino only, never the nucleus', 'C', false, 2),
('d5e15fb9-e5a7-57df-bbec-e35c2e71d94f', '7cf2861c-a516-50de-89f8-3fd912fdac49', 'The proton and the neutron', 'D', false, 3),
('28e7b27f-8c9e-5eef-ba99-8527758d026f', '54a5a971-5d05-5a08-b294-a7e695f0a095', 'It has no momentum', 'A', false, 0),
('d548082c-c29d-5a62-b716-2ad7ac65cd4c', '54a5a971-5d05-5a08-b294-a7e695f0a095', 'It is uncharged', 'B', false, 1),
('ebc621e5-64ac-5ad8-aed2-cc7ab97c2636', '54a5a971-5d05-5a08-b294-a7e695f0a095', 'It decays again at once', 'C', false, 2),
('f3c6b322-d316-5946-8f35-a9fac97d6b44', '54a5a971-5d05-5a08-b294-a7e695f0a095', 'Its large mass means it takes only a few per cent of the energy', 'D', true, 3),
('f7b92a95-feef-5094-ac4d-5d15137574bc', '7bd4552b-b1f1-5af7-aca9-e9b9104cbca2', 'β⁻ decay', 'A', false, 0),
('39c4f94e-a0e3-5982-bf0d-f3d684842228', '7bd4552b-b1f1-5af7-aca9-e9b9104cbca2', 'α decay', 'B', true, 1),
('8d073957-1c03-5d3c-b730-03a2fb19335d', '7bd4552b-b1f1-5af7-aca9-e9b9104cbca2', 'β⁺ decay', 'C', false, 2),
('56c841d8-97f0-5cea-9a0b-9a8948ba2aa8', '7bd4552b-b1f1-5af7-aca9-e9b9104cbca2', 'γ emission', 'D', false, 3),
('e2e6ca77-16c9-5068-bf4a-8102a21da8b9', '1a0ab092-36f2-51dd-ac5d-3bf4a65aa136', 'A single sharp line', 'A', false, 0),
('fa842e71-05a5-58af-bd62-e3cb1e045fb6', '1a0ab092-36f2-51dd-ac5d-3bf4a65aa136', 'Several sharp lines', 'B', false, 1),
('810d0cbe-9cc8-530a-b226-21fcbd638d30', '1a0ab092-36f2-51dd-ac5d-3bf4a65aa136', 'A continuous curve from zero up to a maximum energy', 'C', true, 2),
('71e3bded-663a-572c-8ca7-15b3d3d726d7', '1a0ab092-36f2-51dd-ac5d-3bf4a65aa136', 'A flat line at all energies', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('7ef8d4a9-b126-5207-b857-3e03b91d8520', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 9, 9, 'In a deuteron, one proton (1.007276 u) is bound to one neutron (1.008665 u). The deuteron''s mass is 2.013553 u. By how many u is the deuteron lighter than its separate parts?', NULL, 1, 'numeric'::answer_type, '0.002388', 'u', false, NULL, false, NULL, 'Δm = 1.007276 + 1.008665 − 2.013553 = 0.002388 u. Mark scheme (2 marks). C1: nucleons − nucleus. A1: Δm = 0.002388 u.', 2, NULL, NULL),
('9d629fec-bed9-5d28-8660-d7082c0f25a2', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 10, 10, 'What is the binding energy of a nucleus?', NULL, 1, 'multiple_choice'::answer_type, 'The energy needed to separate it completely into its individual protons and neutrons', NULL, false, NULL, false, NULL, 'It equals the mass defect × c². Mark scheme (1 mark). B1: C (The energy needed to separate it completely into its individual protons and neutrons).', 1, NULL, NULL),
('a226d78f-d62f-504b-9fbe-ea9b2834569e', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 11, 11, 'The mass defect of a deuterium nucleus is 0.002388 u. Taking 1 u as 931.5 MeV, calculate its binding energy.', NULL, 1, 'numeric'::answer_type, '2.224', 'MeV', false, NULL, false, NULL, 'BE = 0.002388 × 931.5 = 2.22 MeV. Mark scheme (2 marks). C1: × 931.5. A1: BE = 2.22 MeV.', 2, NULL, NULL),
('79ad307b-4a55-5e98-821f-250e1903f8eb', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 12, 12, 'Near which nucleon number is the binding energy per nucleon greatest?', NULL, 1, 'multiple_choice'::answer_type, 'About 56 (iron and nickel)', NULL, false, NULL, false, NULL, 'The curve peaks at about 8.8 MeV per nucleon near iron-56. Mark scheme (1 mark). B1: A (About 56 (iron and nickel)).', 1, NULL, NULL),
('6b424aec-34de-596a-8801-e593d7ea6728', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 13, 13, 'Oxygen-16 has a binding energy of 127.6 MeV. Calculate its binding energy per nucleon.', NULL, 1, 'numeric'::answer_type, '7.975', 'MeV', false, NULL, false, NULL, 'BE per nucleon = 127.6 ÷ 16 = 7.97 MeV. Mark scheme (2 marks). C1: ÷ nucleon number. A1: BE/A = 7.97 MeV.', 2, NULL, NULL),
('16cf9ea8-7436-5783-8815-684337e39ab8', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 14, 14, 'How does the mass of a nucleus compare with the total mass of its separate protons and neutrons?', NULL, 1, 'multiple_choice'::answer_type, 'The nucleus has less mass', NULL, false, NULL, false, NULL, 'The difference is the mass defect. Mark scheme (1 mark). B1: D (The nucleus has less mass).', 1, NULL, NULL),
('5ec9f74f-d38f-5a77-9fa0-e87e03d58bbc', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 15, 15, 'Uranium-235 has a binding energy per nucleon of 7.59 MeV. Calculate its total binding energy.', NULL, 1, 'numeric'::answer_type, '1784', 'MeV', false, NULL, false, NULL, 'BE = 235 × 7.59 = 1784 MeV. Mark scheme (2 marks). C1: × A. A1: BE = 1784 MeV.', 2, NULL, NULL),
('4676dbdb-e570-590e-b6c3-cf4a9be57457', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 16, 16, 'A nucleus with a higher binding energy per nucleon is', NULL, 1, 'multiple_choice'::answer_type, 'more stable', NULL, false, NULL, false, NULL, 'Each nucleon is more tightly bound. Mark scheme (1 mark). B1: B (more stable).', 1, NULL, NULL),
('0c371c9f-3d30-5c4e-ad86-24bc843de7ec', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 17, 17, 'Convert a mass defect of 0.100 u into kilograms, in units of 10⁻²⁸ kg. Take 1 u = 1.66 × 10⁻²⁷ kg.', NULL, 1, 'numeric'::answer_type, '1.66', '10⁻²⁸ kg', false, NULL, false, NULL, 'Δm = 0.100 × 1.66 × 10⁻²⁷ = 1.66 × 10⁻²⁸ kg. Mark scheme (2 marks). C1: × 1.66 × 10⁻²⁷. A1: Δm = 1.66 × 10⁻²⁸ kg.', 2, NULL, NULL),
('9ef82933-bb1b-5ce8-b5d5-86cc842ee3ff', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 18, 18, 'Why does the fission of a uranium nucleus release energy?', NULL, 1, 'multiple_choice'::answer_type, 'The fragments have a higher binding energy per nucleon than uranium', NULL, false, NULL, false, NULL, 'Moving towards the peak of the curve releases energy. Mark scheme (1 mark). B1: C (The fragments have a higher binding energy per nucleon than uranium).', 1, NULL, NULL),
('f3545e69-a510-5252-8141-4bd214d66264', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 19, 19, 'The 92.2 MeV needed to pull a carbon-12 nucleus completely apart is shared among its 12 nucleons. What is the average energy per nucleon, in MeV?', NULL, 1, 'numeric'::answer_type, '7.683', 'MeV', false, NULL, false, NULL, 'BE per nucleon = 92.2 ÷ 12 = 7.68 MeV. Mark scheme (2 marks). C1: ÷ 12. A1: BE/A = 7.68 MeV.', 2, NULL, NULL),
('43d0ec6f-3de9-50e5-8c57-53c97d82b772', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 20, 20, 'Which of these nuclei has the lowest binding energy per nucleon?', NULL, 1, 'multiple_choice'::answer_type, 'Hydrogen-2', NULL, false, NULL, false, NULL, 'Deuterium is very weakly bound, at about 1.1 MeV per nucleon. Mark scheme (1 mark). B1: A (Hydrogen-2).', 1, NULL, NULL),
('0a6d0c81-12b5-5827-88b3-55681a73b4cf', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 21, 21, 'Each of the four nucleons in an α-particle is bound by 7.07 MeV on average. What total energy, in MeV, is needed to break the α-particle into separate nucleons?', NULL, 1, 'numeric'::answer_type, '28.28', 'MeV', false, NULL, false, NULL, 'BE = 4 × 7.07 = 28.28 MeV. Mark scheme (2 marks). C1: × A. A1: BE = 28.28 MeV.', 2, NULL, NULL),
('08f058b6-6afd-59fa-86b8-e3e11da2d4e2', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 22, 22, 'In which unit is binding energy per nucleon usually quoted?', NULL, 1, 'multiple_choice'::answer_type, 'MeV per nucleon', NULL, false, NULL, false, NULL, 'It is an energy divided by the number of nucleons. Mark scheme (1 mark). B1: D (MeV per nucleon).', 1, NULL, NULL),
('8b0758f7-8f6b-5425-8ad4-1fe5fe7f6cb4', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 23, 23, 'A helium-4 nucleus is 0.0304 u lighter than its four separate nucleons. Express this mass difference in units of 10⁻²⁹ kg. Take 1 u = 1.66 × 10⁻²⁷ kg.', NULL, 1, 'numeric'::answer_type, '5.046', '10⁻²⁹ kg', false, NULL, false, NULL, 'Δm = 0.0304 × 1.66 × 10⁻²⁷ = 5.05 × 10⁻²⁹ kg. Mark scheme (2 marks). C1: × 1.66 × 10⁻²⁷. A1: Δm = 5.05 × 10⁻²⁹ kg.', 2, NULL, NULL),
('eb33a67f-8e78-5cb2-9190-0d3468e3fd4a', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 24, 24, 'Lithium-7 has a binding energy of 39.2 MeV. How much energy, in units of 10⁻¹² J, is needed to separate it into its nucleons? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '6.272', '10⁻¹² J', false, NULL, false, NULL, 'E = 39.2 × 10⁶ × 1.60 × 10⁻¹⁹ = 6.27 × 10⁻¹² J. Mark scheme (2 marks). C1: MeV to J. A1: E = 6.27 × 10⁻¹² J.', 2, NULL, NULL),
('3b37783a-f0a7-54ba-b296-493ae2d2ff91', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 25, 25, 'Nickel-62 is the most tightly bound nucleus known, with 8.79 MeV per nucleon. How much energy, in MeV, would separate all 62 of its nucleons?', NULL, 1, 'numeric'::answer_type, '545', 'MeV', false, NULL, false, NULL, 'BE = 62 × 8.79 = 545.0 MeV. Mark scheme (1 mark). A1: BE = 545.0 MeV.', 1, NULL, NULL),
('74c33950-0134-5be0-9d3a-fad8784275e2', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 26, 26, 'A lithium-7 nucleus (3 protons, 4 neutrons) has a mass of 7.014357 u. Taking a proton as 1.007276 u and a neutron as 1.008665 u, calculate the mass defect in u.', NULL, 2, 'numeric'::answer_type, '0.04213', 'u', false, NULL, false, NULL, 'Δm = 3 × 1.007276 + 4 × 1.008665 − 7.014357 = 0.04213 u. Mark scheme (3 marks). C1: mass of nucleons. C1: subtract nucleus. A1: Δm = 0.04213 u.', 3, NULL, NULL),
('e15cdc5a-0037-5a59-b32c-07a3029ad4a4', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 27, 27, 'The mass defect of lithium-7 is 0.04213 u. Taking 1 u as 931.5 MeV, calculate its binding energy per nucleon.', NULL, 2, 'numeric'::answer_type, '5.606', 'MeV', false, NULL, false, NULL, 'BE = 0.04213 × 931.5 = 39.24 MeV. BE/A = 39.24 ÷ 7 = 5.61 MeV. Mark scheme (4 marks). C1: BE from Δm. C1: ÷ 7. C1: units. A1: BE/A = 5.61 MeV.', 4, NULL, NULL),
('46d280cd-aae6-5884-8642-c8ae3d2c3210', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 28, 28, 'A carbon-12 nucleus (6 protons, 6 neutrons) has a mass of 11.996709 u. Taking a proton as 1.007276 u, a neutron as 1.008665 u and 1 u as 931.5 MeV, calculate its binding energy.', NULL, 2, 'numeric'::answer_type, '92.16', 'MeV', false, NULL, false, NULL, 'Δm = 6 × 1.007276 + 6 × 1.008665 − 11.996709 = 0.098937 u. BE = 0.098937 × 931.5 = 92.2 MeV. Mark scheme (3 marks). C1: mass defect. C1: × 931.5. A1: BE = 92.2 MeV.', 3, NULL, NULL),
('bdaa90da-f213-5aab-ace8-4f48d5023304', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 29, 29, 'Why must energy be supplied to separate a nucleus into its nucleons?', NULL, 2, 'multiple_choice'::answer_type, 'The strong nuclear force holds the nucleons together; work must be done against it', NULL, false, NULL, false, NULL, 'The work done equals the binding energy. Mark scheme (3 marks). C1: strong force attractive. C1: work done = BE. A1: B (The strong nuclear force holds the nucleons together; work must be done against it).', 3, NULL, NULL),
('c88771b2-cbbd-595b-9413-3ceaf499cfbb', 'aae53119-5afd-4055-b81b-60e6244772d7', 'c7d1948a-561e-56c0-8776-090012819a77', 'a-level', '29.4', '9702 coursebook 29.4 · Mass defect and binding energy', 30, 30, 'Two deuterium nuclei (binding energy 2.22 MeV each) fuse to form helium-4 (binding energy 28.3 MeV). Calculate the energy released.', NULL, 2, 'numeric'::answer_type, '23.86', 'MeV', false, NULL, false, NULL, 'E = 28.3 − 2 × 2.22 = 23.86 MeV. Mark scheme (3 marks). M1: BE(products) − BE(reactants). C1: two deuterons. A1: E = 23.86 MeV.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 300" role="img" aria-labelledby="fge3e974ca-t fge3e974ca-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge3e974ca-t">Fusion on the binding energy curve</title><desc id="fge3e974ca-d">Binding energy per nucleon curve with hydrogen-2 (deuterium) near the bottom left and helium-4 much higher, showing that fusing deuterium into helium releases energy.</desc><line x1="29.4" y1="34" x2="29.4" y2="252" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="104" y1="34" x2="104" y2="252" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="178.5" y1="34" x2="178.5" y2="252" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="253" y1="34" x2="253" y2="252" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="327.5" y1="34" x2="327.5" y2="252" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="402" y1="34" x2="402" y2="252" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="2