="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="178.5" y="264" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">100</text><line x1="253" y1="252" x2="253" y2="256" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="253" y="264" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">150</text><line x1="327.5" y1="252" x2="327.5" y2="256" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="327.5" y="264" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">200</text><line x1="402" y1="252" x2="402" y2="256" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="402" y="264" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">250</text><line x1="25.4" y1="252" x2="29.4" y2="252" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="252" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="25.4" y1="208.4" x2="29.4" y2="208.4" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="208.4" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2</text><line x1="25.4" y1="164.8" x2="29.4" y2="164.8" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="164.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">4</text><line x1="25.4" y1="121.2" x2="29.4" y2="121.2" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="121.2" font-size="12" text-