 x2="29.4" y2="121.2" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="121.2" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">6</text><line x1="25.4" y1="77.6" x2="29.4" y2="77.6" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="77.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">8</text><line x1="25.4" y1="34" x2="29.4" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">10</text><text x="215.7" y="284" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">nucleon number A</text><text x="25.4" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">BE per nucleon / MeV</text><polyline points="32.4,227.8 33.9,196 35.4,97.9 38.4,135.8 39.9,129.7 42.9,111.2 47.3,84.6 50.3,88.1 53.3,83.2 56.3,79.2 59.2,76 62.2,73.3 65.2,71 68.2,69.1 71.2,67.5 74.1,66.1 77.1,64.9 80.1,63.9 83.1,63.1 86.1,62.3 89,61.7 92,61.2 95,60.7 98,60.4 101,60.1 104,59.8 106.9,59.6 109.9,59.5 112.9,59.4 115.9,59.3 118.9,59.3 121.8,59.3 124.8,59.3 127.8,59.3 130.8,59.4 133.8,59.5 136.7,59.6 139.7,59.8 142.7,59.9 145.7,60.1 148.7,60.3 151.6,60.5 154.6,60.7 157.6,60.9 160.6,61.1 163.6,61.4 166.5,61.6 169.5,61.9 172.5,62.1 175.5,62.4 178.5,62.7 181.4,63 184.4,63.3 187.4,63.5 190.4,63.8 193.4,64.1 196.3,64.5 199.3,64.8 202.3,65.1 205.3,65.4 208.3,65.7 211.2,66 214.2,66.4 217.2,66.7 220.2,67 223.2,67.4 226.2,67.7 229.1,68 232.1,68.4 235.1,68.7 238.1,69 241.1,69.4 244,69.7 247,70.1 250,70.4 253,70.8 256,71.1 258.9,71.4 261.9,71.8 264.9,72.1 267.9,72.5 270.9,72.8 273.8,73.2 276.8,73.5 279.8,73.9 282.8,74.2 285.8,74.6 288.7,74.9 291.7,75.3 294.7,75.6 297.7,76 3